/* Tech 3D · Nivell 2 · unitat 4 «Variables i paràmetres» · guia del professorat (p4-1 … p4-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1'] (guia completa). Les diapositives
   «media» mostren el programa (amb colors) i el model 3D que en surt (TMEDIA.model); el camp «code» mostra el programa
   en la llengua de la presentació (les variables de la teoria també es tradueixen: mida/medida, paret/pared). */
Object.assign(TGUIDE, (() => {
  const J = (...l) => l.join('\n');
  // $m, $p, $f → el nom de la variable en cada llengua; «// ca|es» → el comentari de cada llengua
  const NM = { $m: ['mida', 'medida'], $p: ['paret', 'pared'], $f: ['fora', 'fuera'] };
  const V = (src, li) => src.replace(/\$[a-z]/g, k => NM[k][li]).replace(/\/\/ ([^\n|]*)\|([^\n]*)/g, (_, a, b) => '// ' + (li ? b.replace(/^\/\/\s*/, '') : a));
  const BV = src => V(src, 0) + '|' + V(src, 1);
  // el codi de les diapositives: també les paraules del llenguatge en castellà (les línies de comentari no es toquen)
  const KES = { cub: 'cubo', cilindre: 'cilindro', mou: 'mueve', uneix: 'une', con: 'cono', centrat: 'centrado', tub: 'tubo' };
  const CE = src => V(src, 0) + '|' + V(src, 1).split('\n').map(l => /^\s*\/\//.test(l) ? l : l.replace(/\b[a-z]+\b/g, w => KES[w] || w)).join('\n');
  const GRAO = n => J(`$m = ${n}`, 'cub($m)', 'mou($m, 0, 0) cub($m)', 'mou($m, 0, $m) cub($m)');
  const GFIX = n => J(`cub(${n})`, `mou(${n}, 0, 0) cub(${n})`, `mou(${n}, 0, ${n}) cub(${n})`);
  const GSPOT = J('$m = 40', 'cub($m)', 'mou($m, 0, 0) cub($m)', 'mou(30, 0, $m) cub($m)');
  const BOLA = J('bola = 30', 'cilindre(bola, bola)', 'mou(0, 0, bola) esfera(bola)');
  const CENTRE = J('$m = 30', 'cub($m)', 'mou($m / 2, $m / 2, $m) esfera($m / 2)');
  const VIT = J('$m = 30', '$p = 2', 'resta {', '  cub($m + 2 * $p, $m + 2 * $p, $m + $p)', '  mou($p, $p, $p) cub($m, $m, $m + 1)', '}');
  const VITF = J('$m = 30', '$p = 2', '$f = $m + 2 * $p', 'resta {', '  cub($f, $f, $m + $p)', '  mou($p, $p, $p) cub($m, $m, $m + 1)', '}');
  const PLACA = J('base = 40', 'placa = 20', 'cub(base)', 'mou((base - placa) / 2, (base - placa) / 2, base) cub(placa, placa, 4)');
  const PLACAMAL = J('base = 40', 'placa = 20', 'cub(base)', 'mou(base - placa / 2, base - placa / 2, base) cub(placa, placa, 4)');
  const GRAD = J('base = 20', 'cub(base)', 'mou(base, 0, 0) cub(base, base, 2 * base)', 'mou(2 * base, 0, 0) cub(base, base, 3 * base)');
  const GEO = (d, z = 'h + d / 4') => J('// d: el diàmetre de la geoda (mm)|// d: el diámetro de la geoda (mm)', `d = ${d}`, '// mides que depenen de d|// medidas que dependen de d', 'base = d + 10', 'h = d / 4 + 4', 'resta {', '  cilindre(base, h)', `  mou(0, 0, ${z}) esfera(d)`, '}');
  const GEOU = J(GEO(40), "// l'urna, al costat|// la urna, al lado", 'mou(d + 20, 0, 0) resta {', '  cilindre(d + 8, d + 6)', '  mou(0, 0, 2) cilindre(d + 4, d + 6)', '}');
  const BOXV = (ox, oy, oz) => J("// l'objecte: mides en x, y i z (mm)|// el objeto: medidas en x, y y z (mm)", `ox = ${ox}`, `oy = ${oy}`, `oz = ${oz}`, '// les nostres decisions (mm)|// nuestras decisiones (mm)', '$p = 2', 'aire = 1',
    "// per dins: l'objecte i l'aire|// por dentro: el objeto y el aire", 'ix = ox + 2 * aire', 'iy = oy + 2 * aire', 'iz = oz + aire', '// per fora: les parets|// por fuera: las paredes', 'ex = ix + 2 * $p', 'ey = iy + 2 * $p', 'ez = iz + $p');
  const BOXC = J('// la caixa, oberta per dalt|// la caja, abierta por arriba', 'resta {', '  cub(ex, ey, ez)', '  mou($p, $p, $p) cub(ix, iy, iz + 1)', '}');
  const LID = (pos = 'ex + 10') => J('// la tapa, al costat i del revés|// la tapa, al lado y del revés', 'tx = ex + 2 * aire + 2 * $p', 'ty = ey + 2 * aire + 2 * $p', `mou(${pos}, 0, 0) resta {`, '  cub(tx, ty, 10)', '  mou($p, $p, $p) cub(tx - 2 * $p, ty - 2 * $p, 10)', '}');
  const CAIXA = J(BOXV(50, 30, 20), BOXC), FULL = (ox, oy, oz, pos) => J(BOXV(ox, oy, oz), BOXC, LID(pos));
  return {
  /* ---------- Sessió 1 · Variables: canvia un número ---------- */
  'p4-1': {
    obj: ["L'alumne/a crea una variable (mida = 30) i la fa servir a les mides i a les posicions d'un model.|El alumno/a crea una variable (medida = 30) y la usa en las medidas y en las posiciones de un modelo.",
      "L'alumne/a canvia el valor d'una variable i comprova que tot el model s'adapta.|El alumno/a cambia el valor de una variable y comprueba que todo el modelo se adapta.",
      "L'alumne/a crea la variable abans de fer-la servir i li dona un nom clar que no sigui una paraula del llenguatge.|El alumno/a crea la variable antes de usarla y le da un nombre claro que no sea una palabra del lenguaje.",
      "L'alumne/a reconeix que blocs i codi són el mateix programa i escriu línies senzilles a la pestanya «Codi».|El alumno/a reconoce que bloques y código son el mismo programa y escribe líneas sencillas en la pestaña «Código»."],
    comp: ['Tecnologia i digitalització: disseny assistit per ordinador (CAD 3D) amb models que es poden modificar|Tecnología y digitalización: diseño asistido por ordenador (CAD 3D) con modelos que se pueden modificar',
      'Matemàtiques: sentit algebraic, la lletra com a nom d\'un nombre i la substitució|Matemáticas: sentido algebraico, la letra como nombre de un número y la sustitución',
      'Pensament computacional: abstracció (una dada en un sol lloc) i depuració de programes|Pensamiento computacional: abstracción (un dato en un solo sitio) y depuración de programas',
      'Competència digital: el pas de la programació amb blocs a la programació amb text|Competencia digital: el paso de la programación con bloques a la programación con texto'],
    vocab: [['Variable|Variable', 'Un nom que guarda un número; el programa hi posa el número cada vegada que troba el nom.|Un nombre que guarda un número; el programa pone el número cada vez que encuentra el nombre.'],
      ['Valor|Valor', 'El número que guarda la variable en aquell moment (a mida = 30, el valor és 30).|El número que guarda la variable en ese momento (en medida = 30, el valor es 30).'],
      ['Assignar|Asignar', 'Donar un valor a una variable amb el signe =.|Dar un valor a una variable con el signo =.'],
      ['Paraula del llenguatge|Palabra del lenguaje', 'Una paraula que ja vol dir una cosa al programa (cub, mou, resta…) i que no pot ser el nom d\'una variable.|Una palabra que ya significa algo en el programa (cubo, mueve, resta…) y que no puede ser el nombre de una variable.'],
      ['Codi|Código', 'El programa escrit amb text, línia a línia; és el mateix que els blocs.|El programa escrito con texto, línea a línea; es lo mismo que los bloques.']],
    mat: { aula: ['Un ordinador per alumne/a amb Numi Tech obert a la sessió «Variables: canvia un número»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Variables: cambia un número»', 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Per parella: paper quadriculat, un sobre i tres targetes amb els números 2, 3 i 4|Por pareja: papel cuadriculado, un sobre y tres tarjetas con los números 2, 3 y 4'],
      imprimir: ['Fitxa: el graó de la capsa (una per parella)|Ficha: el escalón de la caja (una por pareja)'],
      prep: ['Preparar els sobres amb les targetes.|Preparar los sobres con las tarjetas.', "Provar el repte «Ara a la pestanya Codi»: és el primer que es fa escrivint. Fixar-se en el missatge d'error si s'escriu malament el nom.|Probar el reto «Ahora en la pestaña Código»: es el primero que se hace escribiendo. Fijarse en el mensaje de error si se escribe mal el nombre.", "Tenir a punt a la pissarra l'exemple «cub(mida) abans de mida = 30» per ensenyar l'error.|Tener a punto en la pizarra el ejemplo «cubo(medida) antes de medida = 30» para enseñar el error."] },
    plan: [
      { min: 5, t: 'Un museu ple de mides|Un museo lleno de medidas', fase: 'inici', fa: "Presenta l'encàrrec de la unitat: el museu de ciències naturals necessita peanyes, vitrines, suports i caixes en moltes mides. Recordeu el dau: quants números caldria canviar per fer-lo més gran?|Presenta el encargo de la unidad: el museo de ciencias naturales necesita peanas, vitrinas, soportes y cajas en muchos tamaños. Recordad el dado: ¿cuántos números habría que cambiar para hacerlo más grande?",
        diu: ['Si el client ens demana el mateix objecte en deu mides, quant de temps hi perdrem?|Si el cliente nos pide el mismo objeto en diez tamaños, ¿cuánto tiempo perderemos?'], slides: ['s1', 's2', 's3'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'La capsa amb nom|La caja con nombre', fase: 'teoria', fa: "Comença pel problema: el graó amb el 30 escrit sis vegades. Presenta la variable com una capsa amb etiqueta i fes llegir el programa substituint mida pel seu valor. Mostra que canviant la primera línia tot s'adapta, i explica les regles (crear abans d'usar, noms sense espais i que no siguin del llenguatge). Acaba amb les dues pestanyes, Blocs i Codi.|Empieza por el problema: el escalón con el 30 escrito seis veces. Presenta la variable como una caja con etiqueta y haz leer el programa sustituyendo medida por su valor. Muestra que cambiando la primera línea todo se adapta, y explica las reglas (crear antes de usar, nombres sin espacios y que no sean del lenguaje). Termina con las dos pestañas, Bloques y Código.",
        diu: ['On comença el segon cub si mida val 50?|¿Dónde empieza el segundo cubo si medida vale 50?', 'Què passaria si el cub(mida) anés abans de mida = 30?|¿Qué pasaría si el cubo(medida) fuera antes de medida = 30?'], slides: ['s4', 's5', 's6', 's7', 's8', 's9'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'La capsa de la mida|La caja de la medida', fase: 'desconnectat', fa: "Per parelles, amb el sobre «mida»: un llegeix el programa del graó de la fitxa i l'altre el dibuixa en paper quadriculat amb la targeta del 2; després amb el 3 i el 4. Posa en comú: el programa no ha canviat, només el número del sobre.|Por parejas, con el sobre «medida»: uno lee el programa del escalón de la ficha y el otro lo dibuja en papel cuadriculado con la tarjeta del 2; después con el 3 y el 4. Poned en común: el programa no ha cambiado, solo el número del sobre.",
        diu: ['Què heu hagut de canviar del programa per fer el graó més gran?|¿Qué habéis tenido que cambiar del programa para hacer el escalón más grande?'], slides: ['s10'], app: 'Encara no: paper i llapis.|Todavía no: papel y lápiz.', org: 'Per parelles|Por parejas' },
      { min: 22, t: 'Predir, trobar i programar|Predecir, encontrar y programar', fase: 'ordinador', fa: "Fan la sessió a l'app: la predicció amb la pestanya Codi, el cub que no s'ha adaptat, la pregunta dels noms i els reptes del graó de 40 mm, la columna amb altura i la peanya de la bola escrita al codi (el llapis és extra). Al repte del codi, acompanya'ls a llegir els errors: diuen la línia.|Hacen la sesión en la app: la predicción con la pestaña Código, el cubo que no se ha adaptado, la pregunta de los nombres y los retos del escalón de 40 mm, la columna con altura y la peana de la bola escrita en el código (el lápiz es extra). En el reto del código, acompáñalos a leer los errores: dicen la línea.",
        diu: ["Quina comprovació et falta? Què diu?|¿Qué comprobación te falta? ¿Qué dice?", "El nom que has escrit és exactament el de la variable?|¿El nombre que has escrito es exactamente el de la variable?"], slides: ['s11', 's12', 's13'], app: 'Sessió «Variables: canvia un número», fins a «La teva peanya».|Sesión «Variables: cambia un número», hasta «Tu peana».', org: 'Individual|Individual' },
      { min: 8, t: 'La teva peanya|Tu peana', fase: 'crea', fa: "Dissenyen una peanya o un expositor amb almenys una variable que surti a dos llocs o més. Abans de desar, han de canviar el valor de la variable i comprovar que el model continua ben fet. Es desa a «Projectes».|Diseñan una peana o un expositor con al menos una variable que salga en dos sitios o más. Antes de guardar, tienen que cambiar el valor de la variable y comprobar que el modelo sigue bien hecho. Se guarda en «Proyectos».",
        diu: ['Prova-ho amb un altre valor: tot s\'adapta?|Pruébalo con otro valor: ¿todo se adapta?'], slides: ['s14'], app: 'Pas «La teva peanya».|Paso «Tu peana».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les tres idees clau i el tiquet de sortida.|Repasa las tres ideas clave y el ticket de salida.', diu: ['Per què és millor guardar la mida en una variable?|¿Por qué es mejor guardar la medida en una variable?'], slides: ['s15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Crea la variable després de fer-la servir, i surt «la variable no existeix (encara)».|Crea la variable después de usarla, y sale «la variable no existe (todavía)».", "Recorda que el programa es llegeix de dalt a baix: la línia mida = 30 ha d'anar abans. Als blocs, que seleccioni el bloc de la variable i el pugi amb la fletxa ↑.|Recuerda que el programa se lee de arriba abajo: la línea medida = 30 tiene que ir antes. En los bloques, que seleccione el bloque de la variable y lo suba con la flecha ↑."],
      ["Canvia les mides dels cubs però s'oblida de les posicions dels mou.|Cambia las medidas de los cubos pero se olvida de las posiciones de los mueve.", "Que miri el model de costat i es pregunti on comença el segon cub. Si la posició depèn de la mida, també hi ha d'anar la variable.|Que mire el modelo de lado y se pregunte dónde empieza el segundo cubo. Si la posición depende de la medida, también tiene que ir la variable."],
      ['Al codi, escriu el nom de la variable diferent del que ha creat (bol, Bola, bola2).|En el código, escribe el nombre de la variable distinto del que ha creado (bol, Bola, bola2).', "L'app indica la línia de l'error. Que compari les dues paraules lletra a lletra: el nom ha de ser exactament el mateix.|La app indica la línea del error. Que compare las dos palabras letra a letra: el nombre tiene que ser exactamente el mismo."],
      ['Escriu el número nou a tot arreu en lloc de fer servir la variable.|Escribe el número nuevo en todas partes en lugar de usar la variable.', "Pregunta-li què faria si la Noa en demanés una de 50. Als reptes que tenen la comprovació «Si canvies…», l'app ho detecta.|Pregúntale qué haría si Noa pidiera una de 50. En los retos que tienen la comprobación «Si cambias…», la app lo detecta."]],
    diff: { mes: "Fer el llapis gegant (repte extra) i, després, una peanya amb dues variables on també les posicions depenguin de les variables. Provar d'escriure un programa sencer a la pestanya Codi, sense blocs.|Hacer el lápiz gigante (reto extra) y, después, una peana con dos variables donde también las posiciones dependan de las variables. Probar a escribir un programa entero en la pestaña Código, sin bloques.",
      menys: "Fer els reptes amb blocs i fer servir la pestanya Codi només per mirar-hi el programa. Treballar en parella amb la fitxa de la capsa al costat.|Hacer los retos con bloques y usar la pestaña Código solo para mirar el programa. Trabajar en pareja con la ficha de la caja al lado." },
    aval: { ticket: ['Què vol dir mida = 30 en un programa?|¿Qué quiere decir medida = 30 en un programa?', 'Escriu un programa de dues línies que faci un cub de mida variable.|Escribe un programa de dos líneas que haga un cubo de medida variable.'],
      rubric: [['Crear i fer servir variables|Crear y usar variables', 'Crea la variable al principi i la fa servir a mides i posicions.|Crea la variable al principio y la usa en medidas y posiciones.', 'Crea la variable, però hi deixa algun número escrit a mà.|Crea la variable, pero deja algún número escrito a mano.'],
        ['Regles dels noms|Reglas de los nombres', 'Tria noms clars i respecta les regles sense ajuda.|Elige nombres claros y respeta las reglas sin ayuda.', "De vegades fa servir una paraula del llenguatge o un nom que no coincideix.|A veces usa una palabra del lenguaje o un nombre que no coincide."],
        ['Blocs i codi|Bloques y código', 'Escriu línies al codi i entén que és el mateix programa que els blocs.|Escribe líneas en el código y entiende que es el mismo programa que los bloques.', 'Només fa servir blocs; al codi necessita ajuda.|Solo usa bloques; en el código necesita ayuda.']] },
    casa: "Busca a casa un producte que es vengui en mides diferents (samarretes, gots, piles, llibretes…). Quina mida canvia d'una talla a l'altra i quines es mantenen? Escriu-ho com si fos un programa amb una variable.|Busca en casa un producto que se venda en tamaños distintos (camisetas, vasos, pilas, libretas…). ¿Qué medida cambia de una talla a otra y cuáles se mantienen? Escríbelo como si fuera un programa con una variable.",
    intro: "Primera sessió de la unitat de variables i primera vegada que apareix la pestanya «Codi». L'objectiu és que l'alumnat entengui la variable com un nom que guarda un número, i que vegi el seu gran avantatge en disseny: canviar una mida en un sol lloc i que tot el model s'adapti, també les posicions. La pestanya Codi s'introdueix amb suavitat: primer per mirar-la, després per escriure-hi una línia.|Primera sesión de la unidad de variables y primera vez que aparece la pestaña «Código». El objetivo es que el alumnado entienda la variable como un nombre que guarda un número, y que vea su gran ventaja en diseño: cambiar una medida en un solo sitio y que todo el modelo se adapte, también las posiciones. La pestaña Código se introduce con suavidad: primero para mirarla, después para escribir una línea.",
    claus: ['mida = 30 crea una variable: el programa hi posa 30 cada vegada que troba mida.|medida = 30 crea una variable: el programa pone 30 cada vez que encuentra medida.', "Si les mides i les posicions fan servir la variable, canviant-la tot s'adapta.|Si las medidas y las posiciones usan la variable, cambiándola todo se adapta.", "La variable es crea abans de fer-la servir; el nom, sense espais i que no sigui del llenguatge.|La variable se crea antes de usarla; el nombre, sin espacios y que no sea del lenguaje.", 'Blocs i codi són el mateix programa: es pot canviar de pestanya quan es vulgui (si el codi no té errors).|Bloques y código son el mismo programa: se puede cambiar de pestaña cuando se quiera (si el código no tiene errores).'],
    prev: ["Haver fet les unitats 1 a 3: formes, mou i les operacions booleanes.|Haber hecho las unidades 1 a 3: formas, mueve y las operaciones booleanas.", 'Saber que el cub té una cantonada a l\'origen i el cilindre, el centre de la base.|Saber que el cubo tiene una esquina en el origen y el cilindro, el centro de la base.', 'Fer servir el teclat per escriure números i parèntesis.|Usar el teclado para escribir números y paréntesis.'],
    faq: [['Es poden fer servir accents i majúscules als noms?|¿Se pueden usar acentos y mayúsculas en los nombres?', "Sí: alçada funciona. Però el nom s'ha d'escriure sempre igual, i és més segur fer servir minúscules i paraules curtes.|Sí: altura con acento o sin él funciona. Pero el nombre tiene que escribirse siempre igual, y es más seguro usar minúsculas y palabras cortas."],
      ['Què passa si escric mida = 30 dues vegades?|¿Qué pasa si escribo medida = 30 dos veces?', "A partir de cada línia val el darrer valor. A la sessió que ve veureu que una variable fins i tot es pot canviar a partir d'ella mateixa (mida = mida + 5).|A partir de cada línea vale el último valor. En la sesión que viene veréis que una variable incluso se puede cambiar a partir de sí misma (medida = medida + 5)."],
      ['Per què la pestanya Codi, si amb blocs ja funciona?|¿Por qué la pestaña Código, si con bloques ya funciona?', "Els programes llargs s'escriuen més de pressa amb text, i és el que fan servir els enginyers (OpenSCAD, Python…). En aquesta unitat es poden fer servir tots dos i canviar quan es vulgui; a la unitat 8, el text serà la manera principal.|Los programas largos se escriben más deprisa con texto, y es lo que usan los ingenieros (OpenSCAD, Python…). En esta unidad se pueden usar los dos y cambiar cuando se quiera; en la unidad 8, el texto será la manera principal."]],
    tec: [["L'app no deixa tornar als blocs des del codi.|La app no deja volver a los bloques desde el código.", "Hi ha un error al text i l'app no el pot convertir en blocs. Que llegeixin el missatge vermell (diu la línia) i l'arreglin.|Hay un error en el texto y la app no lo puede convertir en bloques. Que lean el mensaje rojo (dice la línea) y lo arreglen."],
      ['A la tauleta costa escriure al codi.|En la tableta cuesta escribir en el código.', 'A sota del codi hi ha botons amb fragments (cub, mou, { }, +, ×, ÷). També es pot fer tot amb blocs.|Debajo del código hay botones con fragmentos (cubo, mueve, { }, +, ×, ÷). También se puede hacer todo con bloques.'],
      ['El nom de la variable no surt a la llista quan toquen un camp.|El nombre de la variable no sale en la lista cuando tocan un campo.', "La variable ha d'existir al programa (un bloc «variable», millor al principi). Si l'acaben d'afegir, que tornin a tocar el camp.|La variable tiene que existir en el programa (un bloque «variable», mejor al principio). Si la acaban de añadir, que vuelvan a tocar el campo."]],
    seg: ['Fer la pausa activa a mitja sessió per descansar la vista de la pantalla.|Hacer la pausa activa a mitad de sesión para descansar la vista de la pantalla.'],
    extra: ['Fer el llapis gegant amb dues variables i canviar-ne una sola: què es manté?|Hacer el lápiz gigante con dos variables y cambiar una sola: ¿qué se mantiene?', "Escriure el graó expositor sencer a la pestanya Codi, sense mirar-lo.|Escribir el escalón expositor entero en la pestaña Código, sin mirarlo.", "Inventar un programa amb una variable mal posada perquè un company trobi l'error.|Inventar un programa con una variable mal puesta para que un compañero encuentre el error."],
    trans: ['Sessió següent: expressions (mida / 2, mida + 2 * paret) per calcular centres i parets.|Sesión siguiente: expresiones (medida / 2, medida + 2 * pared) para calcular centros y paredes.', 'Matemàtiques: el llenguatge algebraic (lletres que representen nombres).|Matemáticas: el lenguaje algebraico (letras que representan números).'],
    slides: [
      { id: 's1', k: 'portada', t: 'Variables: canvia un número|Variables: cambia un número', x: 'Variables i paràmetres · peanyes per al museu|Variables y parámetros · peanas para el museo', nota: "Presenta l'encàrrec del museu: el mateix objecte en moltes mides.|Presenta el encargo del museo: el mismo objeto en muchos tamaños." },
      { id: 's2', k: 'pregunta', t: 'El dau més gran|El dado más grande', x: 'Per fer el dau de 30 mm en lloc de 20, quants números del programa hauríem de canviar?|Para hacer el dado de 30 mm en lugar de 20, ¿cuántos números del programa tendríamos que cambiar?', nota: "Recull respostes: el cub, l'esfera i els 21 punts. Molts números!|Recoge respuestas: el cubo, la esfera y los 21 puntos. ¡Muchos números!" },
      { id: 's3', k: 'repas', t: 'Recordem|Recordamos', punts: ['El cub té una cantonada a l\'origen.|El cubo tiene una esquina en el origen.', 'mou(x, y, z) posa la forma que ve després.|mueve(x, y, z) pone la forma que viene después.', 'resta { } treu a la primera forma les altres.|resta { } quita a la primera forma las demás.'], nota: 'Repàs ràpid de les unitats anteriors.|Repaso rápido de las unidades anteriores.' },
      { id: 's4', k: 'media', t: 'El mateix número, sis vegades|El mismo número, seis veces', media: { k: 'model', prog: GFIX(30) }, nota: 'Compteu junts quantes vegades hi ha el 30. Què passa si en canvieu cinc i us en deixeu un?|Contad juntos cuántas veces está el 30. ¿Qué pasa si cambiáis cinco y os dejáis uno?' },
      { id: 's5', k: 'anim', t: 'Una capsa amb nom|Una caja con nombre', anim: 'p4var', nota: 'La variable guarda un número; el programa el fa servir on troba el nom.|La variable guarda un número; el programa lo usa donde encuentra el nombre.' },
      { id: 's6', k: 'media', t: 'La variable a tot arreu|La variable en todas partes', media: { k: 'model', prog: BV(GRAO(30)) }, nota: "Llegiu el programa substituint mida per 30. On comença el cub de dalt?|Leed el programa sustituyendo medida por 30. ¿Dónde empieza el cubo de arriba?" },
      { id: 's7', k: 'anim', t: "Un canvi i tot s'adapta|Un cambio y todo se adapta", anim: 'p4adapt', nota: 'Una sola línia canvia: les mides i les posicions es tornen a calcular.|Una sola línea cambia: las medidas y las posiciones se vuelven a calcular.' },
      { id: 's8', k: 'concepte', t: 'Les regles|Las reglas', x: "Primer es crea, després es fa servir. Nom sense espais, que no sigui del llenguatge (cub, mou…) i que digui què guarda.|Primero se crea, después se usa. Nombre sin espacios, que no sea del lenguaje (cubo, mueve…) y que diga qué guarda.", code: CE(J('$m = 30', 'cub($m, $m, 5)')), nota: "Escriu a la pissarra l'ordre equivocat i llegiu el missatge d'error.|Escribe en la pizarra el orden equivocado y leed el mensaje de error." },
      { id: 's9', k: 'anim', t: 'Blocs i codi|Bloques y código', anim: 'p4tabs', nota: "Ensenya les dues pestanyes a l'app: el mateix programa de dues maneres.|Enseña las dos pestañas en la app: el mismo programa de dos maneras." },
      { id: 's10', k: 'activitat', t: 'La capsa de la mida|La caja de la medida', timer: 8, punts: ['El sobre «mida» amb la targeta del 2.|El sobre «medida» con la tarjeta del 2.', 'Un llegeix el programa i l\'altre dibuixa.|Uno lee el programa y el otro dibuja.', 'Canvieu la targeta pel 3 i pel 4.|Cambiad la tarjeta por el 3 y por el 4.'], nota: 'Per parelles, amb la fitxa.|Por parejas, con la ficha.' },
      { id: 's11', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['El graó de 40 mm: un sol número.|El escalón de 40 mm: un solo número.', 'La columna amb altura.|La columna con altura.', 'La peanya de la bola, a la pestanya Codi.|La peana de la bola, en la pestaña Código.'], nota: 'El llapis gegant és un repte extra.|El lápiz gigante es un reto extra.' },
      { id: 's12', k: 'media', t: "Quin cub no s'ha adaptat?|¿Qué cubo no se ha adaptado?", media: { k: 'model', prog: BV(GSPOT), target: V(GRAO(40), 0) }, nota: "El mou de dalt encara diu 30: amb mida = 40 queda desplaçat.|El mueve de arriba todavía dice 30: con medida = 40 queda desplazado." },
      { id: 's13', k: 'pregunta', t: 'Un bon nom?|¿Un buen nombre?', x: 'Quins d\'aquests noms poden ser una variable: mou, alçada, gruix, mida gran?|¿Cuáles de estos nombres pueden ser una variable: mueve, altura, grosor, medida grande?', nota: "mou és del llenguatge i «mida gran» té un espai: no serveixen.|mueve es del lenguaje y «medida grande» tiene un espacio: no sirven." },
      { id: 's14', k: 'repte', t: 'La teva peanya|Tu peana', punts: ['Una variable al principi.|Una variable al principio.', 'Que surti almenys a dos llocs.|Que salga al menos en dos sitios.', 'Canvia-la: tot s\'ha d\'adaptar.|Cámbiala: todo tiene que adaptarse.'], nota: 'Es desa a «Projectes».|Se guarda en «Proyectos».' },
      { id: 's15', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Una variable guarda un número amb un nom.|Una variable guarda un número con un nombre.', "Canviant-la, tot el model s'adapta.|Cambiándola, todo el modelo se adapta.", 'Blocs i codi són el mateix programa.|Bloques y código son el mismo programa.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's16', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Què vol dir mida = 30?|¿Qué quiere decir medida = 30?', 'Escriu un cub de mida variable en dues línies.|Escribe un cubo de medida variable en dos líneas.'], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: el graó de la capsa|Ficha: el escalón de la caja', k: 'fitxa', intro: "El programa del graó, vist de davant (cada cub és un quadrat de mida × mida quadrets). Un company llegeix i l'altre dibuixa; el número és el que hi ha dins del sobre «mida».|El programa del escalón, visto de frente (cada cubo es un cuadrado de medida × medida cuadritos). Un compañero lee y el otro dibuja; el número es el que hay dentro del sobre «medida».",
      items: [{ q: "<code>mida = (el número del sobre)</code><br><code>cub(mida)</code><br><code>mou(mida, 0, 0) cub(mida)</code><br><code>mou(mida, 0, mida) cub(mida)</code><br>Dibuixeu el graó vist de davant.|<code>medida = (el número del sobre)</code><br><code>cubo(medida)</code><br><code>mueve(medida, 0, 0) cubo(medida)</code><br><code>mueve(medida, 0, medida) cubo(medida)</code><br>Dibujad el escalón visto de frente.", big: true, sol: "Tres quadrats de mida × mida: dos a terra, l'un al costat de l'altre, i un a sobre del de la dreta.|Tres cuadrados de medida × medida: dos en el suelo, uno al lado del otro, y uno encima del de la derecha." },
        { q: 'Amb la targeta del 2, quants quadrets fa d\'ample i d\'alt el graó? I amb la del 4?|Con la tarjeta del 2, ¿cuántos cuadritos mide de ancho y de alto el escalón? ¿Y con la del 4?', sol: "Amb 2: 4 d'ample i 4 d'alt. Amb 4: 8 d'ample i 8 d'alt.|Con 2: 4 de ancho y 4 de alto. Con 4: 8 de ancho y 8 de alto." },
        { q: 'Què heu hagut de canviar del programa per fer el graó més gran?|¿Qué habéis tenido que cambiar del programa para hacer el escalón más grande?', sol: "Res: només el número del sobre (el valor de la variable).|Nada: solo el número del sobre (el valor de la variable)." },
        { q: "Escriviu un programa per a una torre de dos cubs, l'un a sobre de l'altre, que faci servir la variable mida.|Escribid un programa para una torre de dos cubos, uno encima del otro, que use la variable medida.", sol: "mida = 3 · cub(mida) · mou(0, 0, mida) cub(mida).|medida = 3 · cubo(medida) · mueve(0, 0, medida) cubo(medida)." }] }]
  },
  /* ---------- Sessió 2 · Expressions: calcular mides ---------- */
  'p4-2': {
    obj: ["L'alumne/a escriu càlculs amb variables als camps (mida / 2, mida + 2 * paret) per calcular mides i posicions.|El alumno/a escribe cálculos con variables en los campos (medida / 2, medida + 2 * pared) para calcular medidas y posiciones.",
      "L'alumne/a aplica la prioritat de les operacions i fa servir parèntesis quan cal.|El alumno/a aplica la prioridad de las operaciones y usa paréntesis cuando hace falta.",
      "L'alumne/a calcula les mides d'una peça buida a partir de la mida de dins i del gruix de la paret.|El alumno/a calcula las medidas de una pieza vacía a partir de la medida de dentro y del grosor de la pared.",
      "L'alumne/a crea variables calculades a partir d'altres per fer el programa més clar.|El alumno/a crea variables calculadas a partir de otras para hacer el programa más claro."],
    comp: ['Matemàtiques: expressions algebraiques, substitució de valors i jerarquia de les operacions|Matemáticas: expresiones algebraicas, sustitución de valores y jerarquía de las operaciones', 'Tecnologia i digitalització: dimensionar peces (parets, centres) en un CAD 3D|Tecnología y digitalización: dimensionar piezas (paredes, centros) en un CAD 3D', 'Pensament computacional: expressions dins dels programes i depuració d\'errors de càlcul|Pensamiento computacional: expresiones dentro de los programas y depuración de errores de cálculo', 'Aprendre a aprendre: comprovar un càlcul de dues maneres (a mà i amb la calculadora)|Aprender a aprender: comprobar un cálculo de dos maneras (a mano y con la calculadora)'],
    vocab: [['Expressió|Expresión', 'Un càlcul amb números, variables i operacions: mida / 2.|Un cálculo con números, variables y operaciones: medida / 2.'], ['Prioritat de les operacions|Prioridad de las operaciones', 'L\'ordre en què es fan els càlculs: primer × i ÷, després + i −.|El orden en que se hacen los cálculos: primero × y ÷, después + y −.'], ['Parèntesis|Paréntesis', 'Fan que el que hi ha dins es calculi primer.|Hacen que lo que hay dentro se calcule primero.'], ['Variable calculada|Variable calculada', 'Una variable que es calcula a partir d\'altres: fora = mida + 2 * paret.|Una variable que se calcula a partir de otras: fuera = medida + 2 * pared.'], ['Centrar|Centrar', 'Posar una peça al mig d\'una altra: la meitat de l\'espai que sobra a cada costat.|Poner una pieza en medio de otra: la mitad del espacio que sobra a cada lado.']],
    mat: { aula: ['Un ordinador per alumne/a amb Numi Tech obert a la sessió «Expressions: calcular mides»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Expresiones: calcular medidas»', 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Una calculadora per parella|Una calculadora por pareja'],
      imprimir: ['Fitxa: targetes de càlcul (una per parella)|Ficha: tarjetas de cálculo (una por pareja)'],
      prep: ["Provar el repte de la placa centrada: és on més s'equivoquen amb els parèntesis.|Probar el reto de la placa centrada: es donde más se equivocan con los paréntesis.", 'Comprovar que les calculadores de l\'aula respecten la prioritat de les operacions.|Comprobar que las calculadoras del aula respetan la prioridad de las operaciones.', 'Tenir a mà una capsa de cartró per ensenyar la paret per dins i per fora.|Tener a mano una caja de cartón para enseñar la pared por dentro y por fuera.'] },
    plan: [
      { min: 5, t: 'Vitrines per als minerals|Vitrinas para los minerales', fase: 'inici', fa: "Presenta l'encàrrec: una vitrina i una placa centrada per a cada mineral. Repàs ràpid: què fa una variable? Ensenya una capsa de cartró: quant fa per dins i per fora?|Presenta el encargo: una vitrina y una placa centrada para cada mineral. Repaso rápido: ¿qué hace una variable? Enseña una caja de cartón: ¿cuánto mide por dentro y por fuera?",
        diu: ['Si el mineral fa 30 mm, quant ha de fer la vitrina?|Si el mineral mide 30 mm, ¿cuánto tiene que medir la vitrina?'], slides: ['s1', 's2', 's3'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 13, t: 'Calcular dins del programa|Calcular dentro del programa', fase: 'teoria', fa: "Explica que qualsevol camp pot ser un càlcul. Amb la bola centrada, calculeu junts mida / 2. Amb la vitrina, dibuixeu-la de dalt: paret, mida, paret. Treballa la prioritat amb els dos càlculs de l'animació i el cas de la placa (els parèntesis). Acaba amb la variable fora.|Explica que cualquier campo puede ser un cálculo. Con la bola centrada, calculad juntos medida / 2. Con la vitrina, dibujadla desde arriba: pared, medida, pared. Trabaja la prioridad con los dos cálculos de la animación y el caso de la placa (los paréntesis). Termina con la variable fuera.",
        diu: ['Per què × 2 a la paret?|¿Por qué × 2 en la pared?', 'Quant fa 30 + 2 × 2? I (30 + 2) × 2?|¿Cuánto da 30 + 2 × 2? ¿Y (30 + 2) × 2?'], slides: ['s4', 's5', 's6', 's7', 's8', 's9'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 9, t: 'Targetes de càlcul|Tarjetas de cálculo', fase: 'desconnectat', fa: "Per parelles: calculen les sis targetes de la fitxa, comparen i ho comproven amb la calculadora. Després escriuen dos càlculs a l'inrevés (la vitrina amb parets de 3 i la placa centrada). Posa en comú els errors de prioritat.|Por parejas: calculan las seis tarjetas de la ficha, comparan y lo comprueban con la calculadora. Después escriben dos cálculos al revés (la vitrina con paredes de 3 y la placa centrada). Pon en común los errores de prioridad.",
        diu: ['On no coincidíeu? Per què?|¿Dónde no coincidíais? ¿Por qué?'], slides: ['s10'], app: 'Encara no: fitxa i calculadora.|Todavía no: ficha y calculadora.', org: 'Per parelles|Por parejas' },
      { min: 20, t: 'Centres, parets i graons|Centros, paredes y escalones', fase: 'ordinador', fa: "Fan la sessió a l'app: la predicció, el càlcul de la paret, la placa que surt per la vora i els reptes de la bola centrada, la vitrina, la placa centrada i la graderia (la tapa amb fora és extra). Recorda'ls que poden fer servir blocs o codi.|Hacen la sesión en la app: la predicción, el cálculo de la pared, la placa que sale por el borde y los retos de la bola centrada, la vitrina, la placa centrada y la gradería (la tapa con fuera es extra). Recuérdales que pueden usar bloques o código.",
        diu: ['La comprovació de «Funciona amb…» és vermella: quin número no depèn de la variable?|La comprobación de «Funciona con…» está en rojo: ¿qué número no depende de la variable?', 'Llegeix el càlcul en veu alta: què es fa primer?|Lee el cálculo en voz alta: ¿qué se hace primero?'], slides: ['s11', 's12', 's13'], app: 'Sessió «Expressions: calcular mides», fins a la vitrina lliure.|Sesión «Expresiones: calcular medidas», hasta la vitrina libre.', org: 'Individual|Individual' },
      { min: 8, t: 'Una vitrina amb càlculs|Una vitrina con cálculos', fase: 'crea', fa: "Dissenyen una vitrina o una peanya per a un mineral amb almenys dues variables i càlculs (centres, parets). Es desa a «Projectes».|Diseñan una vitrina o una peana para un mineral con al menos dos variables y cálculos (centros, paredes). Se guarda en «Proyectos».",
        diu: ["Canvia una variable: tot continua al seu lloc?|Cambia una variable: ¿todo sigue en su sitio?"], slides: ['s14'], app: 'Pas «Una vitrina o una peanya amb càlculs».|Paso «Una vitrina o una peana con cálculos».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.', diu: ['Quan calen parèntesis?|¿Cuándo hacen falta paréntesis?'], slides: ['s15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [['Escriu mida + paret per a la mida de fora i la vitrina queda sense paret en un costat.|Escribe medida + pared para la medida de fuera y la vitrina queda sin pared en un lado.', "Que la dibuixi vista de dalt i compti les parets: n'hi ha una a cada costat, per això × 2.|Que la dibuje vista desde arriba y cuente las paredes: hay una a cada lado, por eso × 2."],
      ['Escriu base - placa / 2 i la placa surt per la vora.|Escribe base - placa / 2 y la placa sale por el borde.', "Que calculi a mà, en l'ordre de la prioritat: primer placa / 2. Si volem restar primer, la resta va entre parèntesis.|Que calcule a mano, en el orden de la prioridad: primero placa / 2. Si queremos restar primero, la resta va entre paréntesis."],
      ["Escriu els resultats calculats a mà (20, 34…) en lloc dels càlculs.|Escribe los resultados calculados a mano (20, 34…) en lugar de los cálculos.", "Funciona per a aquest valor, però no s'adapta: la comprovació «Funciona amb…» es posa vermella. Que deixi que el programa faci el càlcul.|Funciona para este valor, pero no se adapta: la comprobación «Funciona con…» se pone en rojo. Que deje que el programa haga el cálculo."]],
    diff: { mes: "Fer la tapa de la vitrina amb la variable fora (repte extra) i, després, una vitrina rectangular amb dues mides de mineral (llarg i ample). Explicar per escrit per què la placa centrada fa servir (base − placa) / 2.|Hacer la tapa de la vitrina con la variable fuera (reto extra) y, después, una vitrina rectangular con dos medidas de mineral (largo y ancho). Explicar por escrito por qué la placa centrada usa (base − placa) / 2.",
      menys: "Calcular a la fitxa cada mida abans de programar-la i fer els reptes amb blocs, on el teclat de números té × i ÷. Començar per la bola centrada i la graderia, que no tenen parèntesis.|Calcular en la ficha cada medida antes de programarla y hacer los retos con bloques, donde el teclado de números tiene × y ÷. Empezar por la bola centrada y la gradería, que no tienen paréntesis." },
    aval: { ticket: ['Quant val mida + 2 * paret amb mida = 20 i paret = 3?|¿Cuánto vale medida + 2 * pared con medida = 20 y pared = 3?', 'Escriu el càlcul per centrar una placa de 10 mm en una peanya de mida base.|Escribe el cálculo para centrar una placa de 10 mm en una peana de medida base.'],
      rubric: [['Expressions|Expresiones', 'Escriu els càlculs amb variables als camps, sense resultats fets a mà.|Escribe los cálculos con variables en los campos, sin resultados hechos a mano.', 'Barreja càlculs i resultats escrits a mà.|Mezcla cálculos y resultados escritos a mano.'],
        ['Prioritat i parèntesis|Prioridad y paréntesis', 'Aplica la prioritat i posa parèntesis quan cal sense ajuda.|Aplica la prioridad y pone paréntesis cuando hace falta sin ayuda.', 'S\'equivoca amb l\'ordre i ho arregla provant.|Se equivoca con el orden y lo arregla probando.'],
        ['Peces buides|Piezas vacías', 'Calcula la mida de fora a partir de la de dins i de la paret.|Calcula la medida de fuera a partir de la de dentro y de la pared.', "Fa la vitrina, però s'oblida d'una de les parets.|Hace la vitrina, pero se olvida de una de las paredes."]] },
    casa: "Mesura una capsa de casa (de sabates, de galetes…) per dins i per fora. Quant fa la paret? Escriu la fórmula de la mida de fora a partir de la de dins i comprova-la amb els teus números.|Mide una caja de casa (de zapatos, de galletas…) por dentro y por fuera. ¿Cuánto mide la pared? Escribe la fórmula de la medida de fuera a partir de la de dentro y compruébala con tus números.",
    intro: "Sessió de les expressions: les variables deixen de ser només números guardats i passen a fer-se servir en càlculs. Hi ha tres idees que convé treballar a fons: calcular centres (mida / 2), calcular peces buides (per fora = per dins + 2 × paret) i la prioritat de les operacions, que és la causa més freqüent d'errors. La connexió amb el llenguatge algebraic de matemàtiques és directa.|Sesión de las expresiones: las variables dejan de ser solo números guardados y pasan a usarse en cálculos. Hay tres ideas que conviene trabajar a fondo: calcular centros (medida / 2), calcular piezas vacías (por fuera = por dentro + 2 × pared) y la prioridad de las operaciones, que es la causa más frecuente de errores. La conexión con el lenguaje algebraico de matemáticas es directa.",
    claus: ['Qualsevol camp pot ser un càlcul amb + − * / i parèntesis.|Cualquier campo puede ser un cálculo con + − * / y paréntesis.', 'Centre d\'un cub de mida: mida / 2. Centrar una placa: (base − placa) / 2.|Centro de un cubo de medida: medida / 2. Centrar una placa: (base − placa) / 2.', 'Per fora = per dins + 2 × paret, perquè hi ha paret a cada costat.|Por fuera = por dentro + 2 × pared, porque hay pared a cada lado.', 'Primer × i ÷, després + i −; els parèntesis canvien l\'ordre.|Primero × y ÷, después + y −; los paréntesis cambian el orden.'],
    prev: ['Haver fet la sessió «Variables: canvia un número».|Haber hecho la sesión «Variables: cambia un número».', 'Saber fer forats i buidats amb resta (unitat 3).|Saber hacer agujeros y vaciados con resta (unidad 3).', 'Conèixer la prioritat de les operacions de matemàtiques.|Conocer la prioridad de las operaciones de matemáticas.'],
    faq: [['Es pot escriure 2paret en lloc de 2 * paret?|¿Se puede escribir 2pared en lugar de 2 * pared?', "No: al programa la multiplicació sempre s'escriu amb *. Als blocs es veu ×, però és el mateix.|No: en el programa la multiplicación siempre se escribe con *. En los bloques se ve ×, pero es lo mismo."],
      ['Què passa si divideixo per zero?|¿Qué pasa si divido por cero?', "L'app avisa amb un missatge: «no es pot dividir per zero». Passa si una variable que divideix val 0.|La app avisa con un mensaje: «no se puede dividir por cero». Pasa si una variable que divide vale 0."],
      ['Per què la vitrina sobresurt 1 mm per dalt?|¿Por qué la vitrina sobresale 1 mm por arriba?', "És la regla de la unitat 3: l'eina que buida ha de passar de la cara perquè no quedi una pell prima. Aquí el forat fa mida + 1 d'alt.|Es la regla de la unidad 3: la herramienta que vacía tiene que pasar de la cara para que no quede una piel fina. Aquí el agujero mide medida + 1 de alto."]],
    tec: [['No troben el signe de multiplicar al mòbil.|No encuentran el signo de multiplicar en el móvil.', 'Als blocs, el teclat de números té ×, ÷ i parèntesis. Al codi, sota el text hi ha els botons + × ÷ (escriuen * i /).|En los bloques, el teclado de números tiene ×, ÷ y paréntesis. En el código, bajo el texto están los botones + × ÷ (escriben * y /).'],
      ["L'expressió es posa en vermell al camp.|La expresión se pone en rojo en el campo.", "Hi falta un número, un parèntesi o la variable no existeix. El missatge de sota del camp diu què passa.|Falta un número, un paréntesis o la variable no existe. El mensaje de debajo del campo dice qué pasa."],
      ['La comprovació «Funciona amb…» triga una mica.|La comprobación «Funciona con…» tarda un poco.', "L'app torna a fer el model amb altres valors: és normal que tardi un moment.|La app vuelve a hacer el modelo con otros valores: es normal que tarde un momento."]],
    seg: ['Calculadores: recollir-les en acabar.|Calculadoras: recogerlas al acabar.'],
    extra: ['Fer una vitrina rectangular amb dues mides de mineral.|Hacer una vitrina rectangular con dos medidas de mineral.', 'Fer una graderia de quatre graons i calcular quant fa d\'alt.|Hacer una gradería de cuatro escalones y calcular cuánto mide de alto.', "Escriure tres expressions amb un error de prioritat perquè un company les arregli.|Escribir tres expresiones con un error de prioridad para que un compañero las arregle."],
    trans: ['Sessió següent: el disseny paramètric (un sol programa per a qualsevol geoda).|Sesión siguiente: el diseño paramétrico (un solo programa para cualquier geoda).', 'Matemàtiques: jerarquia de les operacions i valor numèric d\'una expressió.|Matemáticas: jerarquía de las operaciones y valor numérico de una expresión.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Expressions: calcular mides|Expresiones: calcular medidas', x: 'Vitrines i plaques per als minerals|Vitrinas y placas para los minerales', nota: "Presenta l'encàrrec: una vitrina i una placa centrada per a cada mineral.|Presenta el encargo: una vitrina y una placa centrada para cada mineral." },
      { id: 's2', k: 'pregunta', t: 'Per dins i per fora|Por dentro y por fuera', x: 'Un mineral fa 30 mm. La vitrina té parets de 2 mm. Quant fa per fora?|Un mineral mide 30 mm. La vitrina tiene paredes de 2 mm. ¿Cuánto mide por fuera?', nota: 'Deixa que discuteixin: 32 o 34? Ho resoldrem amb el dibuix.|Deja que discutan: ¿32 o 34? Lo resolveremos con el dibujo.' },
      { id: 's3', k: 'repas', t: 'Recordem|Recordamos', punts: ['mida = 30 crea una variable.|medida = 30 crea una variable.', 'La variable es crea abans de fer-la servir.|La variable se crea antes de usarla.', 'Blocs i codi són el mateix programa.|Bloques y código son el mismo programa.'], nota: 'Repàs de la sessió anterior.|Repaso de la sesión anterior.' },
      { id: 's4', k: 'anim', t: 'Un camp pot ser un càlcul|Un campo puede ser un cálculo', anim: 'p4expr', nota: 'Al codi, * i /; als blocs, × i ÷.|En el código, * y /; en los bloques, × y ÷.' },
      { id: 's5', k: 'media', t: 'La bola al centre|La bola en el centro', media: { k: 'model', prog: BV(CENTRE) }, nota: 'mida / 2 és el mig de la cara, sigui quina sigui la mida.|medida / 2 es el medio de la cara, sea cual sea la medida.' },
      { id: 's6', k: 'anim', t: 'Per fora = per dins + 2 × paret|Por fuera = por dentro + 2 × pared', anim: 'p4wall', nota: 'Dibuixeu-la de dalt a la pissarra: una paret a cada costat.|Dibujadla desde arriba en la pizarra: una pared a cada lado.' },
      { id: 's7', k: 'media', t: 'La vitrina|La vitrina', media: { k: 'model', prog: BV(VIT) }, nota: "El forat comença a paret de cada cara i sobresurt 1 mm per dalt.|El agujero empieza a pared de cada cara y sobresale 1 mm por arriba." },
      { id: 's8', k: 'anim', t: 'La prioritat|La prioridad', anim: 'p4order', nota: 'Primer × i ÷, després + i −. Els parèntesis manen.|Primero × y ÷, después + y −. Los paréntesis mandan.' },
      { id: 's9', k: 'media', t: 'Una variable calculada|Una variable calculada', media: { k: 'model', prog: BV(VITF) }, nota: 'La mateixa vitrina, però el programa diu què és cada número.|La misma vitrina, pero el programa dice qué es cada número.' },
      { id: 's10', k: 'activitat', t: 'Targetes de càlcul|Tarjetas de cálculo', timer: 9, punts: ['Calculeu les sis targetes.|Calculad las seis tarjetas.', 'Compareu i comproveu amb la calculadora.|Comparad y comprobad con la calculadora.', "Escriviu dos càlculs a l'inrevés.|Escribid dos cálculos al revés."], nota: 'Per parelles, amb la fitxa.|Por parejas, con la ficha.' },
      { id: 's11', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La bola centrada.|La bola centrada.', 'La vitrina buida.|La vitrina vacía.', 'La placa centrada i la graderia.|La placa centrada y la gradería.'], nota: 'La tapa amb la variable fora és un repte extra.|La tapa con la variable fuera es un reto extra.' },
      { id: 's12', k: 'media', t: 'Per què surt per la vora?|¿Por qué sale por el borde?', media: { k: 'model', prog: PLACAMAL, target: PLACA }, nota: 'base − placa / 2 fa 30, no 10: falten els parèntesis.|base − placa / 2 da 30, no 10: faltan los paréntesis.' },
      { id: 's13', k: 'pregunta', t: 'Quant val?|¿Cuánto vale?', x: 'Amb mida = 20, quines mides fa aquest cub?|Con medida = 20, ¿qué medidas tiene este cubo?', code: CE(J('$m = 20', 'cub($m * 2, $m, $m / 2)')), nota: '40 × 20 × 10: una placa llarga i baixa.|40 × 20 × 10: una placa larga y baja.' },
      { id: 's14', k: 'repte', t: 'Una vitrina amb càlculs|Una vitrina con cálculos', punts: ['Almenys dues variables.|Al menos dos variables.', 'Càlculs per a centres i parets.|Cálculos para centros y paredes.', "Prova'n un altre valor.|Prueba otro valor."], nota: 'Es desa a «Projectes».|Se guarda en «Proyectos».' },
      { id: 's15', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['A calcular dins dels camps.|A calcular dentro de los campos.', 'Per fora = per dins + 2 × paret.|Por fuera = por dentro + 2 × pared.', 'Primer × i ÷; els parèntesis canvien l\'ordre.|Primero × y ÷; los paréntesis cambian el orden.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's16', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['mida + 2 * paret amb mida = 20 i paret = 3.|medida + 2 * pared con medida = 20 y pared = 3.', 'Centra una placa de 10 en una peanya de mida base.|Centra una placa de 10 en una peana de medida base.'], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: targetes de càlcul|Ficha: tarjetas de cálculo', k: 'fitxa', intro: 'Amb mida = 30, paret = 2 i placa = 20, calcula cada targeta. Primer × i ÷, després + i −; els parèntesis, abans de tot.|Con medida = 30, pared = 2 y placa = 20, calcula cada tarjeta. Primero × y ÷, después + y −; los paréntesis, antes de todo.',
      items: [{ q: 'mida / 2|medida / 2', sol: '15|15' }, { q: 'mida + 2 * paret|medida + 2 * pared', sol: '30 + 4 = 34|30 + 4 = 34' }, { q: '(mida + 2) * paret|(medida + 2) * pared', sol: '32 × 2 = 64|32 × 2 = 64' },
        { q: '(mida - placa) / 2|(medida - placa) / 2', sol: '10 / 2 = 5|10 / 2 = 5' }, { q: 'mida - placa / 2|medida - placa / 2', sol: '30 − 10 = 20|30 − 10 = 20' }, { q: '3 * mida - paret|3 * medida - pared', sol: '90 − 2 = 88|90 − 2 = 88' },
        { q: "Escriu el càlcul de la mida de fora d'una vitrina per a un mineral de 40 mm amb parets de 3 mm.|Escribe el cálculo de la medida de fuera de una vitrina para un mineral de 40 mm con paredes de 3 mm.", sol: '40 + 2 × 3 = 46 mm (mida + 2 * paret).|40 + 2 × 3 = 46 mm (medida + 2 * pared).' },
        { q: "Escriu la x d'una placa de 20 centrada en una peanya de 40.|Escribe la x de una placa de 20 centrada en una peana de 40.", sol: '(40 − 20) / 2 = 10.|(40 − 20) / 2 = 10.' }] }]
  },
  /* ---------- Sessió 3 · Disseny paramètric ---------- */
  'p4-3': {
    obj: ["L'alumne/a distingeix els paràmetres d'un encàrrec de les mides que en depenen i escriu aquestes amb fórmules.|El alumno/a distingue los parámetros de un encargo de las medidas que dependen de ellos y escribe estas con fórmulas.",
      "L'alumne/a decideix com depèn cada mida (fixa, proporcional o sumada) i ho documenta amb comentaris //.|El alumno/a decide cómo depende cada medida (fija, proporcional o sumada) y lo documenta con comentarios //.",
      "L'alumne/a comprova que un disseny és paramètric de debò provant-lo amb diversos valors i troba els números escrits a mà.|El alumno/a comprueba que un diseño es paramétrico de verdad probándolo con varios valores y encuentra los números escritos a mano.",
      "L'alumne/a fa servir max per posar una mida mínima.|El alumno/a usa max para poner una medida mínima."],
    comp: ['Tecnologia i digitalització: disseny paramètric en CAD 3D i especificacions d\'un encàrrec|Tecnología y digitalización: diseño paramétrico en CAD 3D y especificaciones de un encargo', 'Matemàtiques: relacions entre magnituds (proporcionalitat i suma), fórmules i substitució|Matemáticas: relaciones entre magnitudes (proporcionalidad y suma), fórmulas y sustitución', 'Pensament computacional: generalització i proves amb diversos casos|Pensamiento computacional: generalización y pruebas con varios casos', 'Comunicació: documentar un programa perquè l\'entenguin altres persones|Comunicación: documentar un programa para que lo entiendan otras personas'],
    vocab: [['Paràmetre|Parámetro', "Una mida que ve de l'encàrrec i de la qual depenen les altres (d, el diàmetre de la geoda).|Una medida que viene del encargo y de la que dependen las demás (d, el diámetro de la geoda)."], ['Disseny paramètric|Diseño paramétrico', 'Un disseny on totes les mides es calculen a partir dels paràmetres.|Un diseño donde todas las medidas se calculan a partir de los parámetros.'], ['Dependència|Dependencia', 'La relació entre una mida i les que la fan canviar.|La relación entre una medida y las que la hacen cambiar.'], ['Comentari|Comentario', 'Una línia que comença amb // i que el programa se salta: és per a les persones.|Una línea que empieza con // y que el programa se salta: es para las personas.'], ['max|max', 'Tria el més gran de dos números: max(d + 10, 40).|Elige el mayor de dos números: max(d + 10, 40).']],
    mat: { aula: ['Un ordinador per alumne/a amb Numi Tech obert a la sessió «Disseny paramètric»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Diseño paramétrico»', 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Per grup: tres objectes rodons de mides diferents (pilota de tennis de taula, taronja, bala…), dos llibres i un regle|Por grupo: tres objetos redondos de tamaños distintos (pelota de pimpón, naranja, canica…), dos libros y una regla'],
      imprimir: ['Fitxa: suports per a objectes rodons (una per grup)|Ficha: soportes para objetos redondos (una por grupo)'],
      prep: ['Reunir els objectes rodons (poden ser de casa).|Reunir los objetos redondos (pueden ser de casa).', 'Provar el repte de l\'urna: és el que demana més càlculs alhora.|Probar el reto de la urna: es el que pide más cálculos a la vez.', 'Si teniu impressora 3D, imprimir dos suports de mides diferents amb el mateix programa.|Si tenéis impresora 3D, imprimir dos soportes de tamaños distintos con el mismo programa.'] },
    plan: [
      { min: 5, t: 'Una geoda per a cada suport|Una geoda para cada soporte', fase: 'inici', fa: "Presenta l'encàrrec: suports per a geodes que encara no sabem com seran. Si en teniu, ensenya una geoda o una pedra rodona. Repàs: quant val d / 4 + 4 amb d = 40?|Presenta el encargo: soportes para geodas que todavía no sabemos cómo serán. Si tenéis, enseña una geoda o una piedra redonda. Repaso: ¿cuánto vale d / 4 + 4 con d = 40?",
        diu: ['Com faríem un programa per a una geoda que encara no ha arribat?|¿Cómo haríamos un programa para una geoda que todavía no ha llegado?'], slides: ['s1', 's2', 's3'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Paràmetres i dependències|Parámetros y dependencias', fase: 'teoria', fa: "Explica la diferència entre paràmetres (els dona l'encàrrec) i mides que en depenen. Llegiu el programa del suport i els comentaris. Compareu el suport de 40 i el de 70: què creix igual, què creix proporcionalment i què no canvia. Acaba amb la idea de provar amb diversos valors, que és el que fa la comprovació «Funciona amb…».|Explica la diferencia entre parámetros (los da el encargo) y medidas que dependen de ellos. Leed el programa del soporte y los comentarios. Comparad el soporte de 40 y el de 70: qué crece igual, qué crece proporcionalmente y qué no cambia. Termina con la idea de probar con varios valores, que es lo que hace la comprobación «Funciona con…».",
        diu: ['Quina mida no canvia mai, sigui quina sigui la geoda?|¿Qué medida no cambia nunca, sea cual sea la geoda?', 'Per què un número escrit a mà fa fallar el suport gran?|¿Por qué un número escrito a mano hace fallar el soporte grande?'], slides: ['s4', 's5', 's6', 's7', 's8'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Mesurar coses rodones|Medir cosas redondas', fase: 'desconnectat', fa: "Per grups: mesuren el diàmetre de tres objectes rodons amb el mètode dels dos llibres, calculen a la fitxa les mides del suport de cada un amb les fórmules i discuteixen amb quins valors el suport ja no té sentit.|Por grupos: miden el diámetro de tres objetos redondos con el método de los dos libros, calculan en la ficha las medidas del soporte de cada uno con las fórmulas y discuten con qué valores el soporte ya no tiene sentido.",
        diu: ['Les fórmules han canviat d\'un objecte a l\'altre?|¿Las fórmulas han cambiado de un objeto a otro?'], slides: ['s9'], app: 'Encara no: objectes, regle i fitxa.|Todavía no: objetos, regla y ficha.', org: 'Per grups|Por grupos' },
      { min: 20, t: 'El suport paramètric|El soporte paramétrico', fase: 'ordinador', fa: "Fan la sessió a l'app: la predicció amb d = 20, el niu que forada el suport i els reptes del niu, les mides que depenen de d i l'urna (la base mínima amb max és extra). Insisteix a llegir les comprovacions «Funciona amb…»: si són vermelles, hi ha un número que no depèn de d.|Hacen la sesión en la app: la predicción con d = 20, el nido que agujerea el soporte y los retos del nido, las medidas que dependen de d y la urna (la base mínima con max es extra). Insiste en leer las comprobaciones «Funciona con…»: si están en rojo, hay un número que no depende de d.",
        diu: ['Amb quin valor falla? Què hi ha escrit a mà?|¿Con qué valor falla? ¿Qué hay escrito a mano?', "On és el centre de l'urna? Depèn de d?|¿Dónde está el centro de la urna? ¿Depende de d?"], slides: ['s10', 's11', 's12'], app: 'Sessió «Disseny paramètric», fins al suport lliure.|Sesión «Diseño paramétrico», hasta el soporte libre.', org: 'Individual|Individual' },
      { min: 8, t: 'El teu suport paramètric|Tu soporte paramétrico', fase: 'crea', fa: "Fan un suport per a una altra peça del museu (un ou, una petxina…), amb el paràmetre d al principi i un comentari. Abans de desar, el proven almenys amb tres valors de d. Es desa a «Projectes».|Hacen un soporte para otra pieza del museo (un huevo, una concha…), con el parámetro d al principio y un comentario. Antes de guardar, lo prueban al menos con tres valores de d. Se guarda en «Proyectos».",
        diu: ['Amb quins valors l\'has provat?|¿Con qué valores lo has probado?'], slides: ['s13'], app: 'Pas «El teu suport paramètric».|Paso «Tu soporte paramétrico».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.', diu: ['Com saps que un disseny és paramètric de debò?|¿Cómo sabes que un diseño es paramétrico de verdad?'], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [['Deixa números calculats a mà (base = 50) i les comprovacions «Funciona amb…» es posen vermelles.|Deja números calculados a mano (base = 50) y las comprobaciones «Funciona con…» se ponen en rojo.', "Que canviï d a 60 i miri el model: què no ha crescut? Aquest número s'ha d'escriure amb una fórmula de d.|Que cambie d a 60 y mire el modelo: ¿qué no ha crecido? Ese número tiene que escribirse con una fórmula de d."],
      ["Posa el niu a h (la geoda s'enfonsa la meitat) i el fons queda massa prim.|Pone el nido en h (la geoda se hunde la mitad) y el fondo queda demasiado fino.", "Que dibuixi el tall: el centre de l'esfera és a h + d / 4, perquè la geoda s'enfonsi només un quart.|Que dibuje el corte: el centro de la esfera está en h + d / 4, para que la geoda se hunda solo un cuarto."],
      ["Posa l'urna a una x fixa i, amb geodes grans, se superposa amb el suport.|Pone la urna en una x fija y, con geodas grandes, se superpone con el soporte.", "La posició també és una mida que depèn de d: x = d + 20 deixa sempre espai entre les dues peces.|La posición también es una medida que depende de d: x = d + 20 deja siempre espacio entre las dos piezas."]],
    diff: { mes: "Fer la base mínima amb max (repte extra) i afegir un segon paràmetre al suport (per exemple, l'alçada de la vora). Provar el programa amb valors extrems i escriure en un comentari entre quins valors funciona.|Hacer la base mínima con max (reto extra) y añadir un segundo parámetro al soporte (por ejemplo, la altura del borde). Probar el programa con valores extremos y escribir en un comentario entre qué valores funciona.",
      menys: "Treballar amb la fitxa de fórmules al costat i fer primer el niu i les mides que depenen de d. Deixar l'urna per al final, amb la pista oberta.|Trabajar con la ficha de fórmulas al lado y hacer primero el nido y las medidas que dependen de d. Dejar la urna para el final, con la pista abierta." },
    aval: { ticket: ['Què és un paràmetre? Posa un exemple d\'avui.|¿Qué es un parámetro? Pon un ejemplo de hoy.', 'Si el suport funciona amb d = 40 però no amb d = 60, què hi pot haver al programa?|Si el soporte funciona con d = 40 pero no con d = 60, ¿qué puede haber en el programa?'],
      rubric: [['Paràmetres i fórmules|Parámetros y fórmulas', "Escriu totes les mides com a fórmules dels paràmetres.|Escribe todas las medidas como fórmulas de los parámetros.", 'Escriu la majoria com a fórmules, però en deixa alguna a mà.|Escribe la mayoría como fórmulas, pero deja alguna a mano.'],
        ['Provar amb diversos valors|Probar con varios valores', 'Prova el disseny amb valors diferents i arregla el que falla.|Prueba el diseño con valores distintos y arregla lo que falla.', 'Només el prova amb el valor de l\'encàrrec.|Solo lo prueba con el valor del encargo.'],
        ['Documentar|Documentar', 'Posa comentaris que expliquen cada paràmetre i les seves unitats.|Pone comentarios que explican cada parámetro y sus unidades.', 'Posa pocs comentaris o no diuen què és cada número.|Pone pocos comentarios o no dicen qué es cada número.']] },
    casa: "Busca a casa un objecte que es fabriqui en moltes mides (claus fixes, olles, sabates…). Tria'n un paràmetre (per exemple, la talla) i pensa dues mides que en depenguin. Escriu-ne les fórmules.|Busca en casa un objeto que se fabrique en muchos tamaños (llaves fijas, ollas, zapatos…). Elige un parámetro (por ejemplo, la talla) y piensa dos medidas que dependan de él. Escribe sus fórmulas.",
    intro: "Sessió central de la unitat: el disseny paramètric. Ja no es tracta de fer servir variables en un model, sinó de pensar un model que funcioni per a qualsevol valor dels paràmetres. Les comprovacions «Funciona amb…» fan visible aquesta idea: l'app torna a executar el programa amb altres valors i qualsevol número escrit a mà fa fallar el disseny. També es treballen els comentaris // per documentar els paràmetres.|Sesión central de la unidad: el diseño paramétrico. Ya no se trata de usar variables en un modelo, sino de pensar un modelo que funcione para cualquier valor de los parámetros. Las comprobaciones «Funciona con…» hacen visible esta idea: la app vuelve a ejecutar el programa con otros valores y cualquier número escrito a mano hace fallar el diseño. También se trabajan los comentarios // para documentar los parámetros.",
    claus: ["Els paràmetres (d) van al principi; les altres mides en depenen: base = d + 10, h = d / 4 + 4.|Los parámetros (d) van al principio; las demás medidas dependen de ellos: base = d + 10, h = d / 4 + 4.", 'Cada mida depèn d\'una manera: sumada, proporcional o fixa.|Cada medida depende de una manera: sumada, proporcional o fija.', 'Un disseny paramètric es prova amb diversos valors: un número escrit a mà el fa fallar.|Un diseño paramétrico se prueba con varios valores: un número escrito a mano lo hace fallar.', 'Els comentaris // expliquen què és cada paràmetre; max(a, b) posa un mínim.|Los comentarios // explican qué es cada parámetro; max(a, b) pone un mínimo.'],
    prev: ['Haver fet les sessions de variables i d\'expressions.|Haber hecho las sesiones de variables y de expresiones.', "Saber buidar amb resta i que l'esfera té el centre a l'origen.|Saber vaciar con resta y que la esfera tiene el centro en el origen.", 'Saber calcular fraccions senzilles d\'un número (la meitat, un quart).|Saber calcular fracciones sencillas de un número (la mitad, un cuarto).'],
    faq: [['Quina diferència hi ha entre una variable i un paràmetre?|¿Qué diferencia hay entre una variable y un parámetro?', "Al programa tots dos són variables. Diem paràmetre a la que ve de l'encàrrec i decideix les altres; les altres són variables calculades.|En el programa los dos son variables. Llamamos parámetro a la que viene del encargo y decide las demás; las otras son variables calculadas."],
      ["Com prova l'app el programa amb altres valors?|¿Cómo prueba la app el programa con otros valores?", "Torna a executar el programa canviant el valor del paràmetre (per exemple, d = 30 i d = 60) i comprova que totes les altres condicions continuen complint-se.|Vuelve a ejecutar el programa cambiando el valor del parámetro (por ejemplo, d = 30 y d = 60) y comprueba que todas las demás condiciones se siguen cumpliendo."],
      ['Els enginyers de debò treballen així?|¿Los ingenieros de verdad trabajan así?', "Sí: els programes de CAD paramètric (com OpenSCAD o els de disseny mecànic) guarden les mides com a paràmetres i fórmules, per fer famílies de peces i adaptar-les ràpidament.|Sí: los programas de CAD paramétrico (como OpenSCAD o los de diseño mecánico) guardan las medidas como parámetros y fórmulas, para hacer familias de piezas y adaptarlas rápidamente."]],
    tec: [["La comprovació «Funciona amb…» no es posa verda tot i que el model sembla bé.|La comprobación «Funciona con…» no se pone verde aunque el modelo parece bien.", "Que canviï ell mateix el valor del paràmetre (per exemple, d = 60) i miri què no s'adapta. Després que el torni a deixar com estava.|Que cambie él mismo el valor del parámetro (por ejemplo, d = 60) y mire qué no se adapta. Después que lo vuelva a dejar como estaba."],
      ['Han canviat el nom de la variable d i ja no passa cap comprovació.|Han cambiado el nombre de la variable d y ya no pasa ninguna comprobación.', "Les comprovacions fan servir el nom d. Que el tornin a posar com era.|Las comprobaciones usan el nombre d. Que lo vuelvan a poner como era."],
      ['Els comentaris surten com un bloc als blocs.|Los comentarios salen como un bloque en los bloques.', 'És normal: el bloc «// nota» és un comentari. El programa se\'l salta.|Es normal: el bloque «// nota» es un comentario. El programa se lo salta.']],
    seg: ['Objectes rodons: no llançar-los a classe i retornar-los en acabar.|Objetos redondos: no lanzarlos en clase y devolverlos al acabar.'],
    extra: ['Afegir un segon paràmetre al suport i provar-lo amb diversos valors.|Añadir un segundo parámetro al soporte y probarlo con varios valores.', 'Fer un suport per a un ou (una esfera estirada amb escala) que funcioni amb qualsevol mida.|Hacer un soporte para un huevo (una esfera estirada con escala) que funcione con cualquier tamaño.', "Escriure en un comentari el rang de valors de d amb què funciona el suport.|Escribir en un comentario el rango de valores de d con los que funciona el soporte."],
    trans: ['Sessió següent: el projecte de la caixa a mida amb tapa.|Sesión siguiente: el proyecto de la caja a medida con tapa.', 'Matemàtiques: proporcionalitat i fórmules.|Matemáticas: proporcionalidad y fórmulas.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Disseny paramètric|Diseño paramétrico', x: 'Un sol programa per a qualsevol geoda|Un solo programa para cualquier geoda', nota: "Presenta l'encàrrec: suports per a geodes que encara no han arribat.|Presenta el encargo: soportes para geodas que todavía no han llegado." },
      { id: 's2', k: 'pregunta', t: 'Una geoda desconeguda|Una geoda desconocida', x: "Com podem fer avui el suport d'una geoda que arribarà l'any que ve?|¿Cómo podemos hacer hoy el soporte de una geoda que llegará el año que viene?", nota: "Recull idees: «amb una variable», «amb fórmules». Hi tornarem.|Recoge ideas: «con una variable», «con fórmulas». Volveremos a ello." },
      { id: 's3', k: 'repas', t: 'Recordem|Recordamos', punts: ['Un camp pot ser un càlcul.|Un campo puede ser un cálculo.', 'Primer × i ÷, després + i −.|Primero × y ÷, después + y −.', 'Per fora = per dins + 2 × paret.|Por fuera = por dentro + 2 × pared.'], nota: 'Repàs de la sessió anterior.|Repaso de la sesión anterior.' },
      { id: 's4', k: 'anim', t: 'Paràmetres i dependències|Parámetros y dependencias', anim: 'p4deps', nota: 'd ve de l\'encàrrec; la resta es calcula.|d viene del encargo; lo demás se calcula.' },
      { id: 's5', k: 'media', t: 'El suport de la geoda|El soporte de la geoda', media: { k: 'model', prog: BV(GEO(40)) }, nota: 'Llegiu els comentaris i les fórmules. On és el centre del niu?|Leed los comentarios y las fórmulas. ¿Dónde está el centro del nido?' },
      { id: 's6', k: 'media', t: 'La geoda de 70 mm|La geoda de 70 mm', media: { k: 'model', prog: BV(GEO(70)) }, nota: 'La vora sempre fa 5 mm, el niu és un quart de la geoda i el fons sempre fa 4 mm.|El borde siempre mide 5 mm, el nido es un cuarto de la geoda y el fondo siempre mide 4 mm.' },
      { id: 's7', k: 'anim', t: 'Prova-ho amb diversos valors|Pruébalo con varios valores', anim: 'p4test', nota: "Amb fórmules funciona sempre; amb un número a mà, la geoda gran forada el suport.|Con fórmulas funciona siempre; con un número a mano, la geoda grande agujerea el soporte." },
      { id: 's8', k: 'concepte', t: 'Fix, proporcional o sumat|Fijo, proporcional o sumado', x: "Abans de programar, decidim com depèn cada mida del paràmetre i ho escrivim en un comentari.|Antes de programar, decidimos cómo depende cada medida del parámetro y lo escribimos en un comentario.", code: CE(J('// d: el diàmetre de la geoda (mm)|// d: el diámetro de la geoda (mm)', 'd = 40', 'base = d + 10', 'h = d / 4 + 4')), nota: 'd + 10: sumat · d / 4: proporcional · el fons de 4 mm: fix.|d + 10: sumado · d / 4: proporcional · el fondo de 4 mm: fijo.' },
      { id: 's9', k: 'activitat', t: 'Mesurar coses rodones|Medir cosas redondas', timer: 10, punts: ['Mesureu el diàmetre amb dos llibres.|Medid el diámetro con dos libros.', 'Calculeu el suport amb les fórmules.|Calculad el soporte con las fórmulas.', 'Amb quins valors ja no té sentit?|¿Con qué valores ya no tiene sentido?'], nota: 'Per grups, amb la fitxa.|Por grupos, con la ficha.' },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['El niu de la geoda.|El nido de la geoda.', 'Les mides que depenen de d.|Las medidas que dependen de d.', "L'urna, al costat.|La urna, al lado."], nota: 'La base mínima amb max és un repte extra.|La base mínima con max es un reto extra.' },
      { id: 's11', k: 'media', t: 'Per què forada el suport?|¿Por qué agujerea el soporte?', media: { k: 'model', prog: BV(GEO(60, '14 + d / 4')), target: V(GEO(60), 0) }, nota: "El niu es calcula amb 14 (l'alçada de la geoda de 40), no amb h.|El nido se calcula con 14 (la altura de la geoda de 40), no con h." },
      { id: 's12', k: 'media', t: "L'urna|La urna", media: { k: 'model', prog: BV(GEOU) }, nota: "Un got del revés de d + 8, amb el centre a x = d + 20: mai toca el suport.|Un vaso del revés de d + 8, con el centro en x = d + 20: nunca toca el soporte." },
      { id: 's13', k: 'repte', t: 'El teu suport paramètric|Tu soporte paramétrico', punts: ['El paràmetre d al principi, amb un comentari.|El parámetro d al principio, con un comentario.', 'Totes les mides depenen de d.|Todas las medidas dependen de d.', "Prova'l amb tres valors.|Pruébalo con tres valores."], nota: 'Es desa a «Projectes».|Se guarda en «Proyectos».' },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Paràmetres: les mides de l'encàrrec.|Parámetros: las medidas del encargo.", 'Les altres mides en depenen amb fórmules.|Las demás medidas dependen de ellos con fórmulas.', 'Es prova amb diversos valors.|Se prueba con varios valores.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Què és un paràmetre?|¿Qué es un parámetro?', 'Funciona amb d = 40 i no amb d = 60: per què?|Funciona con d = 40 y no con d = 60: ¿por qué?'], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: suports per a objectes rodons|Ficha: soportes para objetos redondos', k: 'fitxa', intro: "Les fórmules del suport: base = d + 10 · h = d / 4 + 4 · centre del niu = h + d / 4. Totes les mides en mil·límetres.|Las fórmulas del soporte: base = d + 10 · h = d / 4 + 4 · centro del nido = h + d / 4. Todas las medidas en milímetros.",
      items: [{ q: 'Objecte 1: d = ____ mm. base = ____ · h = ____ · centre del niu = ____|Objeto 1: d = ____ mm. base = ____ · h = ____ · centro del nido = ____', sol: "Depèn de l'objecte. Exemple amb d = 40: base 50, h 14, centre del niu a 24.|Depende del objeto. Ejemplo con d = 40: base 50, h 14, centro del nido en 24." },
        { q: 'Objecte 2: d = ____ mm. base = ____ · h = ____ · centre del niu = ____|Objeto 2: d = ____ mm. base = ____ · h = ____ · centro del nido = ____', sol: "Exemple amb d = 70 (una taronja): base 80, h 21,5, centre del niu a 39.|Ejemplo con d = 70 (una naranja): base 80, h 21,5, centro del nido en 39." },
        { q: 'Objecte 3: d = ____ mm. base = ____ · h = ____ · centre del niu = ____|Objeto 3: d = ____ mm. base = ____ · h = ____ · centro del nido = ____', sol: "Exemple amb d = 16 (una bala): base 26, h 8, centre del niu a 12.|Ejemplo con d = 16 (una canica): base 26, h 8, centro del nido en 12." },
        { q: "Quant fa el fons del niu (de la placa fins al punt més baix de la geoda) en els tres casos? Per què?|¿Cuánto mide el fondo del nido (desde la placa hasta el punto más bajo de la geoda) en los tres casos? ¿Por qué?", sol: "Sempre 4 mm: el centre és a h + d / 4 i el radi, d / 2; h + d / 4 − d / 2 = d / 4 + 4 − d / 4 = 4.|Siempre 4 mm: el centro está en h + d / 4 y el radio, d / 2; h + d / 4 − d / 2 = d / 4 + 4 − d / 4 = 4." },
        { q: 'Amb quins valors de d el suport ja no té sentit? Escriu-ho com un comentari del programa.|¿Con qué valores de d el soporte ya no tiene sentido? Escríbelo como un comentario del programa.', sol: "Resposta oberta. Per exemple: // d entre 15 i 180 mm (més petit no s'aguanta; més gran no cap a la placa de 200 mm).|Respuesta abierta. Por ejemplo: // d entre 15 y 180 mm (más pequeño no se aguanta; más grande no cabe en la placa de 200 mm)." }] }]
  },
  /* ---------- Sessió 4 · Projecte: la caixa a mida ---------- */
  'p4-4': {
    obj: ["L'alumne/a planifica una caixa amb tapa de dins cap a fora a partir de les mides d'un objecte, el gruix de la paret i l'aire.|El alumno/a planifica una caja con tapa de dentro hacia fuera a partir de las medidas de un objeto, el grosor de la pared y el aire.",
      "L'alumne/a escriu totes les mides de la caixa i de la tapa com a fórmules dels paràmetres i en troba els errors.|El alumno/a escribe todas las medidas de la caja y de la tapa como fórmulas de los parámetros y encuentra sus errores.",
      "L'alumne/a mesura un objecte real i adapta el programa paramètric a les seves mides.|El alumno/a mide un objeto real y adapta el programa paramétrico a sus medidas.",
      "L'alumne/a col·loca dues peces a la placa perquè s'imprimeixin bé, amb una posició que també depèn de les mides.|El alumno/a coloca dos piezas en la placa para que se impriman bien, con una posición que también depende de las medidas."],
    comp: ['Tecnologia i digitalització: procés tecnològic complet (especificacions, disseny paramètric, revisió) i preparació per a la impressió 3D|Tecnología y digitalización: proceso tecnológico completo (especificaciones, diseño paramétrico, revisión) y preparación para la impresión 3D', 'Matemàtiques: mesura en mil·límetres, ortoedres i fórmules amb diverses variables|Matemáticas: medida en milímetros, ortoedros y fórmulas con varias variables', "Pensament computacional: descomposició (per dins, per fora, tapa) i depuració|Pensamiento computacional: descomposición (por dentro, por fuera, tapa) y depuración", "Sentit d'iniciativa: adaptar un disseny a una necessitat pròpia|Sentido de iniciativa: adaptar un diseño a una necesidad propia"],
    vocab: [['Fitxa tècnica|Ficha técnica', "El document amb les mides i les condicions d'un encàrrec.|El documento con las medidas y las condiciones de un encargo."], ['Aire|Aire', "L'espai lliure que deixem entre l'objecte i la caixa perquè entri i surti fàcilment.|El espacio libre que dejamos entre el objeto y la caja para que entre y salga fácilmente."], ['Interior i exterior|Interior y exterior', 'Les mides de dins (ix…) i de fora (ex…) d\'una peça buida.|Las medidas de dentro (ix…) y de fuera (ex…) de una pieza vacía.'], ['Tapa|Tapa', 'La peça que tanca la caixa; aquí l\'abraça per fora.|La pieza que cierra la caja; aquí la abraza por fuera.'], ['Revisió|Revisión', 'Comprovar un disseny amb un altre cas per trobar-hi errors abans de fabricar.|Comprobar un diseño con otro caso para encontrar errores antes de fabricar.']],
    mat: { aula: ['Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: la caixa a mida»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: la caja a medida»', 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Un regle per alumne/a i un objecte petit per mesurar (goma, maquineta, llapis de memòria…); si en teniu, un peu de rei|Una regla por alumno/a y un objeto pequeño para medir (goma, sacapuntas, memoria USB…); si tenéis, un pie de rey'],
      imprimir: ['Fitxa tècnica de la caixa (una per alumne/a)|Ficha técnica de la caja (una por alumno/a)'],
      prep: ["Demanar el dia abans que portin un objecte petit (que càpiga a la placa amb la seva caixa).|Pedir el día antes que traigan un objeto pequeño (que quepa en la placa con su caja).", 'Provar el pas 3 (la revisió): hi ha dues fórmules equivocades per trobar.|Probar el paso 3 (la revisión): hay dos fórmulas equivocadas que encontrar.', "Si teniu impressora 3D, imprimir la caixa del trilobit per comprovar que la tapa tanca.|Si tenéis impresora 3D, imprimir la caja del trilobites para comprobar que la tapa cierra."] },
    plan: [
      { min: 5, t: 'Fòssils que viatgen|Fósiles que viajan', fase: 'inici', fa: "Presenta el projecte: caixes amb tapa per enviar fòssils a les escoles. Llegiu junts la fitxa tècnica del trilobit i separeu el que diu l'encàrrec del que decidim nosaltres.|Presenta el proyecto: cajas con tapa para enviar fósiles a las escuelas. Leed juntos la ficha técnica del trilobites y separad lo que dice el encargo de lo que decidimos nosotros.",
        diu: ["Per què la caixa no pot fer exactament el que fa el fòssil?|¿Por qué la caja no puede medir exactamente lo que mide el fósil?"], slides: ['s1', 's2', 's3'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'De dins cap a fora|De dentro hacia fuera', fase: 'teoria', fa: "Explica la cadena de mides: objecte → aire → paret → tapa. Fes els càlculs del trilobit a la pissarra (52, 56, 62) i mostra la caixa i la tapa a l'app. Acaba amb l'ammonit: només canvien tres números.|Explica la cadena de medidas: objeto → aire → pared → tapa. Haz los cálculos del trilobites en la pizarra (52, 56, 62) y muestra la caja y la tapa en la app. Termina con el amonites: solo cambian tres números.",
        diu: ['Quant fa la caixa per fora si el fòssil fa 50?|¿Cuánto mide la caja por fuera si el fósil mide 50?', 'Per què la tapa es posa a ex + 10 i no a un número fix?|¿Por qué la tapa se pone en ex + 10 y no en un número fijo?'], slides: ['s4', 's5', 's6', 's7', 's8'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'La fitxa del meu objecte|La ficha de mi objeto', fase: 'desconnectat', fa: "Cada alumne/a mesura el seu objecte en les tres direccions, tria la paret i l'aire, calcula a la fitxa les mides de dins, de fora i de la tapa, i dibuixa el tall de la caixa amb les cotes.|Cada alumno/a mide su objeto en las tres direcciones, elige la pared y el aire, calcula en la ficha las medidas de dentro, de fuera y de la tapa, y dibuja el corte de la caja con las cotas.",
        diu: ["Has mesurat per la part més ampla?|¿Has medido por la parte más ancha?"], slides: ['s9'], app: 'Encara no: regle i fitxa tècnica.|Todavía no: regla y ficha técnica.', org: 'Individual|Individual' },
      { min: 17, t: 'La caixa, la tapa i la revisió|La caja, la tapa y la revisión', fase: 'ordinador', fa: "Fan la sessió a l'app: la predicció amb ox = 70, la tapa que no s'ha adaptat i els tres passos guiats (la caixa, la tapa i la revisió de les dues fórmules equivocades); l'osca és extra. Recorda'ls que llegeixin les comprovacions «Funciona amb…».|Hacen la sesión en la app: la predicción con ox = 70, la tapa que no se ha adaptado y los tres pasos guiados (la caja, la tapa y la revisión de las dos fórmulas equivocadas); la muesca es extra. Recuérdales que lean las comprobaciones «Funciona con…».",
        diu: ["A la revisió: quina fórmula no té 2 × aire o 2 × paret?|En la revisión: ¿qué fórmula no tiene 2 × aire o 2 × pared?"], slides: ['s10', 's11'], app: 'Sessió «Projecte: la caixa a mida», fins al projecte.|Sesión «Proyecto: la caja a medida», hasta el proyecto.', org: 'Individual|Individual' },
      { min: 13, t: 'La caixa del meu objecte|La caja de mi objeto', fase: 'crea', fa: "Posen les mides del seu objecte a ox, oy i oz, ajusten la paret i l'aire si volen i personalitzen la caixa. Abans de desar, un company revisa la fitxa tècnica i el model: hi cap l'objecte? la tapa tanca? Es desa a «Projectes» amb l'STL.|Ponen las medidas de su objeto en ox, oy y oz, ajustan la pared y el aire si quieren y personalizan la caja. Antes de guardar, un compañero revisa la ficha técnica y el modelo: ¿cabe el objeto? ¿la tapa cierra? Se guarda en «Proyectos» con el STL.",
        diu: ['Revisa la caixa del company amb la seva fitxa: coincideixen les mides?|Revisa la caja del compañero con su ficha: ¿coinciden las medidas?'], slides: ['s12', 's13'], app: 'Pas «Projecte: la caixa a mida».|Paso «Proyecto: la caja a medida».', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa què fa que la caixa sigui paramètrica i el tiquet de sortida. Avança la unitat següent: bucles.|Repasa qué hace que la caja sea paramétrica y el ticket de salida. Avanza la unidad siguiente: bucles.', diu: ['Quants números has hagut de canviar per al teu objecte?|¿Cuántos números has tenido que cambiar para tu objeto?'], slides: ['s14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Suma només un aire o una paret (ox + aire) i l'objecte no hi cap.|Suma solo un aire o una pared (ox + aire) y el objeto no cabe.", "Que dibuixi el tall de davant i compti: aire a l'esquerra i a la dreta, paret a l'esquerra i a la dreta. Per això × 2.|Que dibuje el corte de frente y cuente: aire a la izquierda y a la derecha, pared a la izquierda y a la derecha. Por eso × 2."],
      ["Fa la tapa de la mida de la caixa per dins, i no hi encaixa.|Hace la tapa de la medida de la caja por dentro, y no encaja.", "La tapa abraça la caixa per fora: per dins ha de fer ex + 2 × aire, i per fora, encara 2 × paret més.|La tapa abraza la caja por fuera: por dentro tiene que medir ex + 2 × aire, y por fuera, todavía 2 × pared más."],
      ['Posa la tapa a una x fixa i, amb objectes grans, es fica dins de la caixa.|Pone la tapa en una x fija y, con objetos grandes, se mete dentro de la caja.', 'La posició també depèn de les mides: mou(ex + 10, 0, 0).|La posición también depende de las medidas: mueve(ex + 10, 0, 0).'],
      ["Mesura malament l'objecte (en centímetres o per la part estreta).|Mide mal el objeto (en centímetros o por la parte estrecha).", "Que torni a mesurar en mil·límetres i per la part més ampla, i que arrodoneixi cap amunt.|Que vuelva a medir en milímetros y por la parte más ancha, y que redondee hacia arriba."]],
    diff: { mes: "Fer l'osca de la tapa (repte extra) i afegir-hi les inicials o un separador interior. Calcular quanta folgança necessita la tapa si s'imprimeix i provar-ho (connecta amb les toleràncies de la unitat 7).|Hacer la muesca de la tapa (reto extra) y añadir las iniciales o un separador interior. Calcular cuánta holgura necesita la tapa si se imprime y probarlo (conecta con las tolerancias de la unidad 7).",
      menys: "Fer els passos guiats amb la pista i, al projecte, només canviar ox, oy i oz amb les mides de l'objecte. La fitxa tècnica feta a mà ajuda a comprovar els resultats.|Hacer los pasos guiados con la pista y, en el proyecto, solo cambiar ox, oy y oz con las medidas del objeto. La ficha técnica hecha a mano ayuda a comprobar los resultados." },
    aval: { ticket: ["Un objecte fa 40 × 20 × 10 mm. Amb paret = 2 i aire = 1, quant fa la caixa per fora?|Un objeto mide 40 × 20 × 10 mm. Con pared = 2 y aire = 1, ¿cuánto mide la caja por fuera?", 'Per què la tapa es posa a ex + 10?|¿Por qué la tapa se pone en ex + 10?'],
      rubric: [['Planificació|Planificación', "Fa la fitxa tècnica i el tall amb totes les cotes abans de programar.|Hace la ficha técnica y el corte con todas las cotas antes de programar.", "Fa la fitxa, però li falta alguna mida o alguna cota.|Hace la ficha, pero le falta alguna medida o alguna cota."],
        ['Disseny paramètric|Diseño paramétrico', 'Totes les mides i la posició de la tapa són fórmules dels paràmetres.|Todas las medidas y la posición de la tapa son fórmulas de los parámetros.', 'Hi ha alguna mida escrita a mà que no s\'adapta.|Hay alguna medida escrita a mano que no se adapta.'],
        ['Revisió|Revisión', "Revisa el disseny amb un altre objecte i troba els errors.|Revisa el diseño con otro objeto y encuentra los errores.", "Troba els errors amb ajuda de les comprovacions o d'un company.|Encuentra los errores con ayuda de las comprobaciones o de un compañero."]] },
    casa: "Tria un altre objecte de casa que voldries guardar en una caixa. Mesura'l i omple una fitxa tècnica nova: quines mides tindrien la caixa i la tapa? Si vols, explica a casa com el programa ho calcularia sol.|Elige otro objeto de casa que querrías guardar en una caja. Mídelo y rellena una ficha técnica nueva: ¿qué medidas tendrían la caja y la tapa? Si quieres, explica en casa cómo el programa lo calcularía solo.",
    intro: "Projecte de la unitat: una caixa amb tapa feta a mida per a qualsevol objecte, que reuneix variables, expressions i disseny paramètric. Els passos guiats construeixen el programa per parts (la caixa, la tapa) i acaben amb una revisió, com fan els enginyers abans de fabricar. Al projecte, l'alumnat mesura un objecte propi i adapta el programa. L'«aire» és un marge generós perquè l'objecte entri bé; a la unitat 7 s'estudiaran les toleràncies dels encaixos ajustats.|Proyecto de la unidad: una caja con tapa hecha a medida para cualquier objeto, que reúne variables, expresiones y diseño paramétrico. Los pasos guiados construyen el programa por partes (la caja, la tapa) y terminan con una revisión, como hacen los ingenieros antes de fabricar. En el proyecto, el alumnado mide un objeto propio y adapta el programa. El «aire» es un margen generoso para que el objeto entre bien; en la unidad 7 se estudiarán las tolerancias de los encajes ajustados.",
    claus: ['De dins cap a fora: ix = ox + 2 × aire; ex = ix + 2 × paret; tx = ex + 2 × aire + 2 × paret.|De dentro hacia fuera: ix = ox + 2 × aire; ex = ix + 2 × pared; tx = ex + 2 × aire + 2 × pared.', "En alçada, un sol fons i un sol aire: iz = oz + aire, ez = iz + paret (per dalt és oberta).|En altura, un solo fondo y un solo aire: iz = oz + aire, ez = iz + pared (por arriba es abierta).", 'La tapa s\'imprimeix del revés al costat de la caixa, a x = ex + 10.|La tapa se imprime del revés al lado de la caja, en x = ex + 10.', 'Per a un objecte nou, només canvien ox, oy i oz.|Para un objeto nuevo, solo cambian ox, oy y oz.'],
    prev: ['Haver fet les tres sessions anteriors de la unitat.|Haber hecho las tres sesiones anteriores de la unidad.', 'Saber buidar una caixa amb resta (unitat 3).|Saber vaciar una caja con resta (unidad 3).', 'Saber mesurar en mil·límetres amb el regle.|Saber medir en milímetros con la regla.'],
    faq: [["Per què 1 mm d'aire i no més?|¿Por qué 1 mm de aire y no más?", "És un marge còmode per a objectes mesurats amb regle. Amb més aire l'objecte balla dins de la caixa; amb menys, pot no entrar. Es pot canviar: és un paràmetre.|Es un margen cómodo para objetos medidos con regla. Con más aire el objeto baila dentro de la caja; con menos, puede no entrar. Se puede cambiar: es un parámetro."],
      ['Per què la tapa és més gran que la caixa?|¿Por qué la tapa es más grande que la caja?', "Perquè l'abraça per fora, com la d'una capsa de sabates. Hi ha altres maneres de fer tapes (amb un llavi que entra a dins), que es veuen a la unitat 7.|Porque la abraza por fuera, como la de una caja de zapatos. Hay otras maneras de hacer tapas (con un labio que entra dentro), que se ven en la unidad 7."],
      ["Per què la tapa s'imprimeix del revés?|¿Por qué la tapa se imprime del revés?", "Perquè la cara plana quedi sobre la placa i la impressora no hagi de fer el sostre a l'aire.|Para que la cara plana quede sobre la placa y la impresora no tenga que hacer el techo en el aire."]],
    tec: [['El programa és llarg i costa trobar-hi una línia.|El programa es largo y cuesta encontrar una línea.', "Que facin servir els comentaris com a títols: «per dins», «per fora», «la tapa». Al codi, tocar una peça del 3D marca la seva línia.|Que usen los comentarios como títulos: «por dentro», «por fuera», «la tapa». En el código, tocar una pieza del 3D marca su línea."],
      ["L'objecte de l'alumne/a és massa gran i la caixa no cap a la placa.|El objeto del alumno/a es demasiado grande y la caja no cabe en la placa.", "La placa fa 200 × 200 mm: caixa i tapa han de cabre l'una al costat de l'altra. Que triï un objecte més petit o posi la tapa en y.|La placa mide 200 × 200 mm: caja y tapa tienen que caber una al lado de la otra. Que elija un objeto más pequeño o ponga la tapa en y."],
      ["La comprovació de l'objecte no es posa verda al projecte.|La comprobación del objeto no se pone verde en el proyecto.", "Comprova que no han canviat les fórmules de ix, iy i iz ni el + 1 de l'alçada del forat.|Comprueba que no han cambiado las fórmulas de ix, iy e iz ni el + 1 de la altura del agujero."]],
    seg: ['Regles i peus de rei: fer-los servir amb compte i retornar-los en acabar.|Reglas y pies de rey: usarlos con cuidado y devolverlos al acabar.', 'Si s\'imprimeix, no tocar el capçal ni la placa calenta.|Si se imprime, no tocar el cabezal ni la placa caliente.'],
    extra: ["Fer l'osca de la tapa i les inicials en relleu.|Hacer la muesca de la tapa y las iniciales en relieve.", "Afegir un separador interior per guardar dos objectes.|Añadir un separador interior para guardar dos objetos.", "Fer una caixa de base rodona per a un objecte cilíndric (d, h, paret, aire).|Hacer una caja de base redonda para un objeto cilíndrico (d, h, pared, aire)."],
    trans: ['Unitat següent: bucles i patrons (repetir peces amb el comptador).|Unidad siguiente: bucles y patrones (repetir piezas con el contador).', 'Matemàtiques: ortoedres, mesura i fórmules amb diverses variables.|Matemáticas: ortoedros, medida y fórmulas con varias variables.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Projecte: la caixa a mida|Proyecto: la caja a medida', x: 'Una caixa amb tapa per a qualsevol objecte|Una caja con tapa para cualquier objeto', nota: "Presenta l'encàrrec: caixes per enviar fòssils a les escoles.|Presenta el encargo: cajas para enviar fósiles a las escuelas." },
      { id: 's2', k: 'pregunta', t: 'Per què no fa el mateix?|¿Por qué no mide lo mismo?', x: 'Si el fòssil fa 50 mm, per què la caixa no pot fer 50 mm per dins?|Si el fósil mide 50 mm, ¿por qué la caja no puede medir 50 mm por dentro?', nota: "Que surti la idea d'aire: les mides reals no són perfectes i l'objecte s'ha de poder treure.|Que salga la idea de aire: las medidas reales no son perfectas y el objeto se tiene que poder sacar." },
      { id: 's3', k: 'repas', t: 'Recordem|Recordamos', punts: ['Paràmetres al principi, mides que en depenen.|Parámetros al principio, medidas que dependen de ellos.', 'Per fora = per dins + 2 × paret.|Por fuera = por dentro + 2 × pared.', 'Provar amb diversos valors.|Probar con varios valores.'], nota: 'Tot el que farem servir avui.|Todo lo que usaremos hoy.' },
      { id: 's4', k: 'anim', t: 'La fitxa tècnica|La ficha técnica', anim: 'p4spec', nota: "L'encàrrec ens dona ox, oy i oz; nosaltres decidim la paret i l'aire.|El encargo nos da ox, oy y oz; nosotros decidimos la pared y el aire." },
      { id: 's5', k: 'anim', t: 'De dins cap a fora|De dentro hacia fuera', anim: 'p4layers', nota: 'Feu els càlculs del trilobit a la pissarra: 52, 56 i 62.|Haced los cálculos del trilobites en la pizarra: 52, 56 y 62.' },
      { id: 's6', k: 'media', t: 'La caixa|La caja', media: { k: 'model', prog: BV(CAIXA) }, nota: 'Un cub de fora menys un de dins que sobresurt 1 mm per dalt.|Un cubo de fuera menos uno de dentro que sobresale 1 mm por arriba.' },
      { id: 's7', k: 'media', t: 'La caixa i la tapa|La caja y la tapa', media: { k: 'model', prog: BV(FULL(50, 30, 20)) }, nota: 'La tapa abraça la caixa per fora i s\'imprimeix del revés al costat.|La tapa abraza la caja por fuera y se imprime del revés al lado.' },
      { id: 's8', k: 'media', t: 'Un altre fòssil|Otro fósil', media: { k: 'model', prog: BV(FULL(40, 40, 15)) }, nota: "Per a l'ammonit, només canvien ox, oy i oz.|Para el amonites, solo cambian ox, oy y oz." },
      { id: 's9', k: 'activitat', t: 'La fitxa del meu objecte|La ficha de mi objeto', timer: 10, punts: ['Mesureu ox, oy i oz en mil·límetres.|Medid ox, oy y oz en milímetros.', 'Calculeu dins, fora i la tapa.|Calculad dentro, fuera y la tapa.', 'Dibuixeu el tall amb les cotes.|Dibujad el corte con las cotas.'], nota: 'Individual, amb la fitxa tècnica.|Individual, con la ficha técnica.' },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Pas 1: la caixa.|Paso 1: la caja.', 'Pas 2: la tapa.|Paso 2: la tapa.', 'Pas 3: la revisió amb l\'ammonit.|Paso 3: la revisión con el amonites.'], nota: "L'osca de la tapa és un repte extra.|La muesca de la tapa es un reto extra." },
      { id: 's11', k: 'media', t: 'La tapa que no es mou|La tapa que no se mueve', media: { k: 'model', prog: BV(FULL(80, 30, 20, '66')), target: V(FULL(80, 30, 20), 0) }, nota: "La tapa és a x = 66 per a tots els objectes: amb ox = 80 es fica dins de la caixa.|La tapa está en x = 66 para todos los objetos: con ox = 80 se mete dentro de la caja." },
      { id: 's12', k: 'repte', t: 'La caixa del meu objecte|La caja de mi objeto', punts: ['Les mides del teu objecte a ox, oy i oz.|Las medidas de tu objeto en ox, oy y oz.', 'Tot amb fórmules: cap mida a mà.|Todo con fórmulas: ninguna medida a mano.', 'Caixa i tapa a la placa.|Caja y tapa en la placa.'], nota: 'Es desa a «Projectes» amb l\'STL.|Se guarda en «Proyectos» con el STL.' },
      { id: 's13', k: 'concepte', t: 'La revisió entre iguals|La revisión entre iguales', x: "Abans de desar, un company compara la fitxa tècnica amb el model: hi cap l'objecte? la tapa tanca? hi ha alguna mida escrita a mà?|Antes de guardar, un compañero compara la ficha técnica con el modelo: ¿cabe el objeto? ¿la tapa cierra? ¿hay alguna medida escrita a mano?", nota: 'Que la revisió sigui amable i concreta: una cosa que està bé i una per millorar.|Que la revisión sea amable y concreta: una cosa que está bien y una para mejorar.' },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['A calcular una caixa de dins cap a fora.|A calcular una caja de dentro hacia fuera.', 'Que tot depengui dels paràmetres.|Que todo dependa de los parámetros.', 'A revisar un disseny abans de fabricar-lo.|A revisar un diseño antes de fabricarlo.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Caixa per a 40 × 20 × 10 amb paret 2 i aire 1: quant fa per fora?|Caja para 40 × 20 × 10 con pared 2 y aire 1: ¿cuánto mide por fuera?', 'Per què la tapa es posa a ex + 10?|¿Por qué la tapa se pone en ex + 10?'], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' },
      { id: 's16', k: 'concepte', t: 'Unitat següent: bucles|Unidad siguiente: bucles', x: "Si la Noa volgués deu caixes en fila, o una caixa amb vint compartiments… les variables ens ajudaran a repetir peces amb els bucles.|Si Noa quisiera diez cajas en fila, o una caja con veinte compartimentos… las variables nos ayudarán a repetir piezas con los bucles.", nota: 'Avança la unitat 5.|Avanza la unidad 5.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa tècnica de la caixa|Ficha técnica de la caja', k: 'fitxa', intro: "Mesura el teu objecte en mil·límetres (per la part més ampla) i calcula les mides de la caixa i de la tapa amb les fórmules. Després dibuixa el tall de la caixa vist de davant amb totes les cotes.|Mide tu objeto en milímetros (por la parte más ancha) y calcula las medidas de la caja y de la tapa con las fórmulas. Después dibuja el corte de la caja visto de frente con todas las cotas.",
      items: [{ q: "L'objecte: ox = ____ mm · oy = ____ mm · oz = ____ mm. Les meves decisions: paret = ____ mm · aire = ____ mm|El objeto: ox = ____ mm · oy = ____ mm · oz = ____ mm. Mis decisiones: pared = ____ mm · aire = ____ mm", sol: "Depèn de l'objecte. Exemple, el trilobit: 50 · 30 · 20, paret 2 i aire 1.|Depende del objeto. Ejemplo, el trilobites: 50 · 30 · 20, pared 2 y aire 1." },
        { q: 'Per dins: ix = ox + 2 · aire = ____ · iy = ____ · iz = oz + aire = ____|Por dentro: ix = ox + 2 · aire = ____ · iy = ____ · iz = oz + aire = ____', sol: 'Trilobit: 52 · 32 · 21.|Trilobites: 52 · 32 · 21.' },
        { q: 'Per fora: ex = ix + 2 · paret = ____ · ey = ____ · ez = iz + paret = ____|Por fuera: ex = ix + 2 · pared = ____ · ey = ____ · ez = iz + pared = ____', sol: 'Trilobit: 56 · 36 · 23.|Trilobites: 56 · 36 · 23.' },
        { q: 'La tapa: tx = ex + 2 · aire + 2 · paret = ____ · ty = ____ · alçada 10 mm. Posició: x = ex + 10 = ____|La tapa: tx = ex + 2 · aire + 2 · pared = ____ · ty = ____ · altura 10 mm. Posición: x = ex + 10 = ____', sol: 'Trilobit: 62 · 42, a x = 66.|Trilobites: 62 · 42, en x = 66.' },
        { q: "Caben la caixa i la tapa a la placa de 200 × 200 mm, l'una al costat de l'altra? Calcula-ho: ex + 10 + tx = ____|¿Caben la caja y la tapa en la placa de 200 × 200 mm, una al lado de la otra? Calcúlalo: ex + 10 + tx = ____", sol: "Trilobit: 56 + 10 + 62 = 128 mm: sí que hi caben.|Trilobites: 56 + 10 + 62 = 128 mm: sí caben." }] }]
  }
  };
})());
